            ["Ck_DrvHint"] = "Windows зберігає старі версії драйвера в сховищі драйверів. Тут показано драйвери, збережені більше ніж один раз, і яка копія використовується або найновіша. Старі копії нешкідливі: вони лише займають місце й можуть дозволити відкат. «Відкрити теку» показує файли вибраної копії. «Видалити вибране…» видаляє копії зі станом «Старіший, не використовується» через pnputil /delete-driver (ніколи не /force, тож Windows відмовить, якщо пристрій ще використовує драйвер); найновіша копія, копії в користуванні та копії без дати чи імені oemNN.inf не пропонуються.",
            ["Ck_Drv_NewestInUse"] = "Найновіший, використовується",
            ["Ck_Drv_OlderInUse"] = "Старіший, використовується",
            ["Ck_Drv_NewestUnused"] = "Найновіший, не використовується",
            ["Ck_Drv_OlderUnused"] = "Старіший, не використовується",
            ["Ck_DrvSummary"] = "Драйверів, збережених більше ніж раз: {0}; старіші копії, що не використовуються, займають {1}.",
            ["Tab_Settings"] = "Налаштування",
            ["Set_ModeTitle"] = "Режим",
            ["Set_ViewOnly"] = "Режим лише перегляду",
            ["Set_ViewOnlyHint"] = "BG Optimizer лише спостерігає й показує, що зробив би. Він не уповільнює, не заморожує, не стискає й не закриває процеси, не змінює автозапуск, служби, налаштування безпеки чи твіки, не очищає файли й не створює точки відновлення. Авто-оптимізація продовжує працювати й записує в журнал, що вона зробила б. Усе, що вона вже уповільнила чи заморозила, звільняється під час вмикання.",
            ["Set_ViewOnlyBanner"] = "Режим лише перегляду ввімкнено: нічого не змінюється.",
            ["Msg_ViewOnlyNothingChanged"] = "Режим лише перегляду ввімкнено, тож нічого не змінено. Вимкніть його в Налаштуваннях, щоб вносити зміни.",
            ["Msg_ViewOnlyBlocked"] = "Режим лише перегляду ввімкнено: «{0}» не змінено.",
            ["Msg_ViewOnlyOn"] = "Режим лише перегляду ввімкнено: програма лише спостерігає. Усе, що вона уповільнила чи заморозила, звільнено.",
            ["Msg_ViewOnlyOff"] = "Режим лише перегляду вимкнено: програма знову може вносити зміни.",
            ["Msg_ViewOnlyWouldThrottle"] = "Лише перегляд: знизила б пріоритет і стиснула б ОЗУ «{0}» (PID {1}), що простоює у фоні.",
            ["Msg_ViewOnlyWouldSuspend"] = "Лише перегляд: заморозила б «{0}» (PID {1}), що довго простоює.",
            ["Set_ViewOnlyNoSelect"] = "Поки режим увімкнено, рядки в списках «Процеси», «Автозавантаження» та «Служби» не можна вибирати.",
            ["Set_CodeTitle"] = "Захист кодом",
            ["Set_CodeHint"] = "Встановіть секретний код (щонайменше 8 символів), щоб режим лише перегляду міг вимкнути лише той, хто його знає. Код і режим зберігаються там, де їх може змінити лише адміністратор, тому інші програми, що працюють від вашого імені, не зможуть вимкнути захист редагуванням файлу. Адміністратора це не зупинить. Забули код? Від імені адміністратора видаліть розділ реєстру HKEY_LOCAL_MACHINE\\SOFTWARE\\BgOptimizer.",
