            ["Msg_ViewOnlyNotSaved"] = "Не вдалося зберегти налаштування режиму лише перегляду чи коду (для запису в захищене сховище потрібні права адміністратора), тож воно не збережеться після перезапуску.",
            ["Msg_ViewOnlyCodeLegacy"] = "У settings.json знайдено старий захист кодом із версії 1.2.0; йому більше не довіряють (цей файл може змінити будь-яка програма, що працює від вашого імені). Встановіть новий код у Налаштуваннях, щоб знову заблокувати режим лише перегляду.",
            ["Set_LoadTitle"] = "Навантаження системи",
