            ["Set_LoadAlertHint"] = "Приблизно через 15 с вище ліміту в журнал записується рядок із найзавантаженішими програмами, а якщо вікно приховано — показується сповіщення в треї (не частіше ніж раз на 5 хвилин для кожного навантаження). Поки це ввімкнено, програма оновлює дані й у треї.",
