            ["St_DetailLocked"] = "Вимкнення для цього елемента заблоковано (захисне ПЗ, компонент Windows або ця програма). Увімкнути його все одно можна.",
            ["St_DetailReadOnly"] = "Цей вид запису тут не перемикається. Скористайтеся кнопкою «Відкрити налаштування автозапуску Windows» або налаштуваннями самої програми.",
            ["St_OpenSettings"] = "Відкрити налаштування автозапуску Windows",
            ["Msg_StartupReadOnly"] = "«{0}» тут не перемикається (запис лише для читання). Скористайтеся Параметри Windows > Програми > Автозавантаження.",
            ["Msg_StartupLocked"] = "«{0}» захищено (захисне ПЗ, компонент Windows або ця програма), тому його не можна вимкнути тут.",
