            ["Ck_DrvDelete"] = "Видалити вибране…",
            ["Ck_DrvNoneDeletable"] = "Нічого видаляти. Виберіть рядки зі станом «Старіший, не використовується» (або натисніть «Вибрати старі, невикористовувані»).",
            ["Ck_DrvDeleteMsg"] = "Ці старі копії драйверів буде видалено зі сховища драйверів Windows через pnputil (ніколи не /force, тож Windows відмовить, якщо пристрій ще використовує драйвер). Спершу створюється точка відновлення, якщо цей параметр увімкнено. Видалену копію звідси повернути не можна.",
            ["Ck_DrvRemoved"] = "Старий драйвер {0} ({1}) видалено зі сховища драйверів.",
            ["Ck_DrvRemoveFailed"] = "Не вдалося видалити драйвер {0}: {1}",
            ["Ck_DrvNotRemovable"] = "«{0}» не видалено: можна видаляти лише старіші копії, що не використовуються.",
            ["Ck_DrvRemovedTotal"] = "Видалено старих копій драйверів: {0}; звільнено приблизно {1}.",
            ["Set_LoadOptimize"] = "Оптимізувати автоматично, коли навантаження тримається вище ліміту",
            ["Set_LoadOptimizeHint"] = "Приблизно через 15 секунд вище ліміту у фонових програм, що якийсь час простоювали, звільняється ОЗП, а пріоритет знижується до «Нижче звичайного»; так триває, доки кожне навантаження не опуститься щонайменше на 5 пунктів під ліміт. Програма, якою ви користуєтеся, браузери, аудіододатки, засоби безпеки та ШІ-інструменти не чіпаються, і нічого не заморожується (заморожування лишається прив'язаним до малого обсягу вільної ОЗП). У режимі лише перегляду в журнал записується лише те, що було б зроблено. Поки це ввімкнено, застосунок оновлюється і в треї.",
            ["Msg_LegacyStartupFixed"] = "Виправлено елементів автозавантаження, що лишилися від старої версії: {0}. Вони залишаються вимкненими, а Windows більше не питає, чим їх відкрити.",
            ["Msg_ThresholdCapped"] = "Поріг вільної ОЗП знижено з {0} GB до {1} GB — це третина від {2} GB цього ПК. Інакше автооптимізація працювала б постійно й без кінця стискала б програми.",
            ["Msg_ProcessPlatform"] = "'{0}' — допоміжний процес Windows або драйвера обладнання (живлення, Wi-Fi, безпека чи графіка), тому його ніколи не уповільнюють, не стискають і не заморожують. Уповільнення таких процесів може порушити сплячий режим і пробудження.",
            ["Msg_ProcessUserProtected"] = "'{0}' є у вашому списку «не чіпати» в Налаштуваннях, тому його ніколи не уповільнюють, не стискають і не заморожують.",
            ["Msg_RulesCleared"] = "Вилучено {0} постійних правил уповільнення для програм, які не можна уповільнювати: {1}.",
            ["Set_NeverTitle"] = "Програми, яких не чіпати",
            ["Set_NeverHint"] = "Назви програм через кому, наприклад: AnyDesk, MyVpnClient. Автооптимізація та інші дії, що уповільнюють, їх пропускають. Додайте робочі агенти, які простоюють, але мають лишатися доступними: віддалений доступ, VPN, чат, пошта, синхронізація, менеджери паролів.",
            ["Set_NeverName"] = "Програми, яких не чіпати, назви через кому",
            ["Set_CoolTitle"] = "Охолодження",
            ["Set_CoolHint"] = "Швидкістю вентилятора керує вбудоване програмне забезпечення ноутбука (на ASUS: MyASUS, режим вентилятора). У Windows немає безпечного інтерфейсу для вентилятора, а ця програма не встановлює драйверів. Обмеження максимальної швидкості процесора — єдиний важіль, що зменшує нагрів і шум вентилятора на будь-якому ноутбуці. Оновлюється кожні 5 с, поки вікно відкрите.",
            ["Set_CoolTemp"] = "Температура: {0} °C",
            ["Set_CoolTempNone"] = "Температура: цей ноутбук не повідомляє її Windows",
            ["Set_CoolSpeed"] = "Швидкість процесора: {0}% від максимуму{1}",
            ["Set_CoolOk"] = "Windows не уповільнює процесор для охолодження.",
            ["Set_CoolThrottled"] = "▲ Windows уповільнює процесор для охолодження (дозволено: {0}%).",
            ["Set_CoolLimit"] = "Обмеження швидкості процесора:",
            ["Set_CoolNone"] = "Без обмеження",
            ["Set_CoolApply"] = "Застосувати обмеження",
            ["Set_CoolCurrent"] = "Поточна схема живлення: від мережі {0}%, від батареї {1}%",
            ["Set_CoolUnavailable"] = "Ця схема живлення не має обмеження швидкості процесора.",

            ["Ck_Drv_OlderUnusedBuiltIn"] = "Старіший, вбудований у Windows",
            ["Ck_DrvBuiltInName"] = "вбудований",
            ["Ck_DrvOnlyBuiltIn"] = "Нічого видаляти: вибрані старіші копії — це вбудовані драйвери самої Windows (у них немає імені oemNN.inf). Замінити їх може лише Windows, і прибирати їх не потрібно. Старіші копії драйверів, встановлених пізніше (наприклад, від AMD, Intel чи ASUS), мають ім’я oemNN.inf, і їх можна видалити.",
            ["Ck_DrvBuiltInKept"] = "Старіших вбудованих копій Windows залишено без змін: {0}. Вони належать Windows і звідси не видаляються.",

            ["Set_WindowTitle"] = "Вікно",
            ["Set_KeepTray"] = "Залишати програму в треї, коли я закриваю вікно",
            ["Set_KeepTrayHint"] = "Кнопка закриття лише ховає вікно, а програма продовжує працювати: сповіщення про навантаження й автооптимізація не припиняються, а значок лишається біля годинника (він може бути за стрілкою ^). Щоб вийти, клацніть значок правою кнопкою й виберіть «Вийти». Вимкніть цей параметр, щоб кнопка закриття повністю виходила з програми.",
            ["Msg_TrayStillRunning"] = "Програма працює в треї. Щоб вийти, клацніть цей значок правою кнопкою й виберіть «Вийти».",

            ["Btn_RestartExplorer"] = "Перезапустити Провідник",
            ["Btn_RestartExplorerHint"] = "Перезапускає оболонку Windows: панель завдань, Пуск і вікна Провідника. Провідник розростається за кілька днів роботи, і повернути цю пам’ять можна лише перезапуском.",
            ["Dlg_ExplorerTitle"] = "Перезапустити Провідник Windows?",
            ["Dlg_ExplorerMessage"] = "Панель завдань, робочий стіл і всі відкриті вікна Провідника закриються й за кілька секунд повернуться. Копіювання файлів у вікні Провідника буде перервано. Інші програми продовжують працювати.",
            ["Msg_BlockedExplorer"] = "«{0}» — це оболонка Windows, тому її не можна завершити, уповільнити чи стиснути звідси. Щоб скинути її пам’ять, скористайтеся «Перезапустити Провідник».",
            ["Msg_ExplorerRestarted"] = "Провідник Windows перезапущено (він займав {0} МБ).",
            ["Msg_ExplorerNotFound"] = "У цьому сеансі не знайдено оболонку Провідника для перезапуску.",
            ["Msg_ExplorerNotBack"] = "Провідник закрито, але Windows не запустила новий за 15 секунд. Натисніть Ctrl+Shift+Esc, виберіть «Запустити нове завдання» й введіть explorer.",
            ["Msg_ExplorerNoAutoRestart"] = "Не перезапущено: Windows налаштована не перезапускати оболонку сама (або використовується інша оболонка), тож закриття Провідника могло б залишити вас без робочого столу.",
            ["Msg_ExplorerFailed"] = "Не вдалося перезапустити Провідник: {0}",

            ["Set_NeverIntro"] = "Програма ніколи не уповільнює, не стискає й не заморожує ці програми. Вбудований список діє завжди; нижче можна додати власні назви.",
            ["Set_NeverBuiltIn"] = "Завжди захищено (вбудований список, не вимикається): назв програм — {0}, груп — {1}.",
            ["Set_NeverShowList"] = "Показати, що захищено",
            ["Set_NeverOwn"] = "Ваш власний список",
            ["Set_NeverPick"] = "Додати із запущених програм…",
            ["Set_NeverPickTitle"] = "Додати запущені програми",
            ["Set_NeverPickHint"] = "Позначте програми, які не можна уповільнювати, стискати чи заморожувати. Спочатку — найбільші за пам’яттю; уже захищені програми не показано.",
