            ["Pw_Title"] = "Параметри схеми живлення",
            ["Pw_Hint"] = "Змінюють активну схему живлення окремо для роботи від мережі та від батареї. Кожна зміна підтверджується, потім перевіряється, а «Скасувати» повертає її. Схему може змінювати й програма ноутбука (наприклад, MyASUS).",
            ["Pw_ActivePlan"] = "Активна схема живлення: {0}",
