            ["Pw_Reading"] = "Зчитування параметрів живлення…",
            ["Pw_AdviceNone"] = "У цих параметрах немає нічого незвичного.",
            ["Pw_AdviceMinCpu"] = "Мінімальний стан процесора: {0}% від мережі та {1}% від батареї. Процесору не дозволено простоювати на нижчій швидкості, через що більше тепла й шуму вентилятора. Збалансована схема Windows використовує 5%.",
            ["Pw_AdvicePerf"] = "Від мережі схема просить у процесора максимальну продуктивність (пріоритет енергії {0}, агресивний режим підвищення). Це найшвидший варіант, а також найгарячіший і найгучніший. Якщо заважає вентилятор, збільште пріоритет енергії або виберіть «Ефективний» режим підвищення.",
            ["Pw_AdviceMinAboveMax"] = "Мінімальний стан процесора ({0}% / {1}%) вищий за обмеження швидкості процесора ({2}% / {3}%). Тоді Windows може тримати процесор на межі обмеження навіть у простої.",
            ["Pw_AdviceSleep"] = "Від мережі ноутбук засинає через {0} хв. Кожне засинання й пробудження — це ще один шанс на проблему драйвера чи мікропрограми під час виходу зі сну; довший час або «Ніколи» від мережі означає їх менше.",
