            ["Pw_HibernateAfter"] = "Глибокий сон через", ["Pw_HibernateAfter_d"] = "Скільки ноутбук спить, перш ніж зберегти все на диск і вимкнутися — тоді батарея не витрачається.",
            ["Pw_WakeTimers"] = "Таймери пробудження", ["Pw_WakeTimers_d"] = "Чи можуть заплановані завдання й програми будити ноутбук зі сну.",
