            ["Pw_Aspm"] = "Економія енергії лінії PCI Express", ["Pw_Aspm_d"] = "Дозволяє лінії до SSD і відеокарти простоювати в нижчому енергетичному стані. «Вимкнено» — найсумісніше.",
