            ["Msg_SecurityFailed"] = "Error en el cambio de seguridad de {0}: {1}",
            ["Chk_AllowInteractiveThrottle"] = "Permitir limitar apps interactivas",
            ["Chk_AllowInteractiveThrottleHint"] = "Permite establecer prioridad Inactiva/Por debajo de lo normal en navegadores, shells y otras apps interactivas. Desactivado por defecto porque puede causar lentitud visible al cambiar a ellas. Los procesos de seguridad/críticos del sistema siguen protegidos en cualquier caso.",
            ["Chk_AutoOptimize"] = "Auto-optimizar (según RAM)",
            ["Chk_AutoOptimizeHint"] = "Vigila la RAM libre cada 5 s. Cuando baja del umbral, los procesos en segundo plano inactivos (cerca de 0% de CPU) durante un tiempo reciben un recorte de RAM y prioridad Por debajo de lo normal. Nunca toca el navegador, el shell ni la app en primer plano. Lo restaura todo automáticamente cuando la RAM se recupera.",
            ["Lbl_FreeRamBelow"] = "RAM libre por debajo de:",
            ["Chk_AllowSuspend"] = "Permitir suspender apps inactivas mucho tiempo",
