            ["Dlg_AutoSuspendTitle"] = "¿Permitir la suspensión automática?",
            ["Dlg_AutoSuspendMessage"] = "Auto-optimizar empezará a congelar (0% de CPU) las apps en segundo plano inactivas durante unos 5 minutos siempre que la RAM libre baje de tu umbral, sin confirmación por app. Los antivirus/EDR/agentes de copia de seguridad conocidos nunca se suspenden. Puedes reanudarlo todo en cualquier momento con «Reanudar todas las suspendidas» y desactivarlo desmarcando «Permitir suspender apps inactivas mucho tiempo».",
