            ["Ck_LeftTitle"] = "Programas eliminados: restos y archivos aún en memoria",
            ["Ck_LeftHint"] = "Busca (1) carpetas de Program Files que no pertenecen a ningún programa instalado, (2) entradas de Aplicaciones instaladas cuyos archivos ya no existen y (3) programas en ejecución o con bibliotecas cargadas desde archivos que se eliminaron del disco. Reinicia esos programas para liberarlos. Revisa una carpeta antes de borrarla: puede pertenecer a software instalado sin un desinstalador normal.",
