            ["Ck_Col_Provider"] = "Proveedor",
            ["Ck_DupTitle"] = "Archivos duplicados",
            ["Ck_DupHint"] = "Busca archivos con contenido idéntico (mismo tamaño y luego el mismo hash SHA-256) de 1 MB o más. De forma predeterminada mira en Descargas, Documentos, Escritorio, Imágenes, Vídeos y Música. Los archivos solo en la nube se omiten para no descargar nada. No se borra nada: conserva tú una copia de cada grupo.",
            ["Ck_DupScanDefault"] = "Analizar mis carpetas",
            ["Ck_DupScanFolder"] = "Elegir carpeta…",
