            ["Ck_DupProgress"] = "Analizando… {0} archivo(s) revisado(s)",
            ["Ck_DupComparing"] = "Comparando {0} archivo(s) candidato(s)…",
            ["Ck_DupSummary"] = "{0} grupo(s) de archivos idénticos; conservar una copia de cada uno liberaría {1}.",
            ["Ck_DrvTitle"] = "Controladores duplicados",
            ["Ck_DrvHint"] = "Windows guarda versiones antiguas de un controlador en su almacén de controladores. Aquí se listan los controladores guardados más de una vez y se indica qué copia está en uso o es la más reciente. Las copias antiguas son inofensivas: solo ocupan espacio y pueden permitir una reversión. «Abrir carpeta» muestra los archivos de la copia seleccionada. «Quitar selección…» elimina las copias marcadas como «Más antigua, sin usar» con pnputil /delete-driver (nunca con /force, así que Windows rechaza las que un dispositivo aún use); la copia más reciente, las que están en uso y las que no tienen fecha o nombre oemNN.inf nunca se ofrecen.",
            ["Ck_Drv_NewestInUse"] = "Más reciente, en uso",
            ["Ck_Drv_OlderInUse"] = "Más antigua, en uso",
            ["Ck_Drv_NewestUnused"] = "Más reciente, sin usar",
            ["Ck_Drv_OlderUnused"] = "Más antigua, sin usar",
            ["Ck_DrvSummary"] = "{0} controlador(es) guardado(s) más de una vez; las copias antiguas sin usar ocupan {1}.",
            ["Tab_Settings"] = "Ajustes",
            ["Set_ModeTitle"] = "Modo",
            ["Set_ViewOnly"] = "Modo solo lectura",
            ["Set_ViewOnlyHint"] = "BG Optimizer solo observa y muestra lo que haría. No ralentiza, congela, recorta ni cierra procesos, no cambia elementos de inicio, servicios, ajustes de seguridad ni tweaks, no limpia archivos ni crea puntos de restauración. La optimización automática sigue funcionando y anota en el registro lo que habría hecho. Lo que ya hubiera ralentizado o congelado se libera al activarlo.",
            ["Set_ViewOnlyBanner"] = "Modo solo lectura activado: no se está cambiando nada.",
            ["Msg_ViewOnlyNothingChanged"] = "El modo solo lectura está activado, así que no se cambió nada. Desactívalo en Ajustes para hacer cambios.",
            ["Msg_ViewOnlyBlocked"] = "Modo solo lectura activado: «{0}» no se cambió.",
            ["Msg_ViewOnlyOn"] = "Modo solo lectura activado: la aplicación solo observa. Lo que había ralentizado o congelado se ha liberado.",
            ["Msg_ViewOnlyOff"] = "Modo solo lectura desactivado: la aplicación puede volver a hacer cambios.",
            ["Msg_ViewOnlyWouldThrottle"] = "Solo lectura: bajaría la prioridad y recortaría la RAM de «{0}» (PID {1}), inactivo en segundo plano.",
            ["Msg_ViewOnlyWouldSuspend"] = "Solo lectura: congelaría «{0}» (PID {1}), inactivo desde hace mucho.",
            ["Set_ViewOnlyNoSelect"] = "Mientras está activado, no se pueden seleccionar filas en las listas Procesos, Aplicaciones de inicio y Servicios.",
            ["Set_CodeTitle"] = "Bloqueo con código",
            ["Set_CodeHint"] = "Define un código secreto (mínimo 8 caracteres) para que el modo solo lectura solo pueda desactivarlo quien lo conozca. El código y el modo se guardan donde solo un administrador puede cambiarlos, así que otros programas que se ejecutan como tú no pueden quitar el bloqueo editando un archivo. No detiene a un administrador. ¿Olvidaste el código? Como administrador, elimina la clave del registro HKEY_LOCAL_MACHINE\\SOFTWARE\\BgOptimizer.",
            ["Set_CodeOn"] = "Bloqueo con código: activado",
