            ["Msg_ViewOnlyCodeLegacy"] = "Se encontró en settings.json un bloqueo con código antiguo de la versión 1.2.0 y ya no se considera fiable (cualquier programa que se ejecute como tú puede editar ese archivo). Define un código nuevo en Ajustes para volver a bloquear el modo solo lectura.",
