            ["Ck_DrvDeleteMsg"] = "Estas copias antiguas de controladores se quitarán del almacén de controladores de Windows con pnputil (nunca con /force, así que Windows rechaza las que un dispositivo aún use). Antes se crea un punto de restauración si esa opción está activada. Desde aquí no se puede recuperar una copia quitada.",
            ["Ck_DrvRemoved"] = "Se quitó el controlador antiguo {0} ({1}) del almacén de controladores.",
