            ["Ck_DrvRemovedTotal"] = "Copias antiguas de controladores quitadas: {0}; se liberaron unos {1}.",
            ["Set_LoadOptimize"] = "Optimizar automáticamente cuando la carga se mantenga por encima del límite",
            ["Set_LoadOptimizeHint"] = "Tras unos 15 segundos por encima del límite, a los programas en segundo plano que llevan un rato inactivos se les libera RAM y se les baja la prioridad a «Por debajo de lo normal»; dura hasta que todas las cargas estén al menos 5 puntos por debajo del límite. Nunca se toca el programa que usas, los navegadores, las apps de audio, el software de seguridad ni las herramientas de IA, y no se congela nada (congelar sigue ligado a poca RAM libre). En modo solo lectura solo anota en el registro lo que haría. La app sigue actualizándose en la bandeja mientras esto esté activado.",
            ["Msg_LegacyStartupFixed"] = "Se repararon {0} elemento(s) de inicio que dejó una versión anterior. Siguen desactivados y Windows ya no pregunta con qué aplicación abrirlos.",
            ["Msg_ThresholdCapped"] = "El umbral de RAM libre se redujo de {0} GB a {1} GB, un tercio de los {2} GB de este equipo. De lo contrario, la optimización automática estaría siempre activa y recortaría programas sin parar.",
            ["Msg_ProcessPlatform"] = "'{0}' es un auxiliar de Windows o de un controlador de hardware (energía, Wi-Fi, seguridad o gráficos), por lo que nunca se ralentiza, recorta ni congela. Ralentizarlos puede perturbar la suspensión y la reanudación.",
            ["Msg_ProcessUserProtected"] = "'{0}' está en tu lista de «no tocar» de Configuración, por lo que nunca se ralentiza, recorta ni congela.",
            ["Msg_RulesCleared"] = "Se quitaron {0} regla(s) permanentes de ralentización de programas que no deben ralentizarse: {1}.",
            ["Set_NeverTitle"] = "Programas que nunca se tocan",
            ["Set_NeverHint"] = "Nombres de programas separados por comas, por ejemplo: AnyDesk, MyVpnClient. La optimización automática y cualquier otra acción de ralentización los omiten. Añade agentes de trabajo que están inactivos pero deben seguir disponibles: acceso remoto, VPN, chat, correo, sincronización, gestores de contraseñas.",
            ["Set_NeverName"] = "Programas que nunca se tocan, nombres separados por comas",
            ["Set_CoolTitle"] = "Refrigeración",
            ["Set_CoolHint"] = "La velocidad del ventilador la fija el firmware del propio portátil (en ASUS: MyASUS, modo de ventilador). Windows no tiene una interfaz segura para el ventilador y esta aplicación no instala ningún controlador. Limitar la velocidad máxima de la CPU es la única palanca que reduce el calor y el ruido del ventilador en cualquier portátil. Se actualiza cada 5 segundos mientras esta ventana está abierta.",
            ["Set_CoolTemp"] = "Temperatura: {0} °C",
            ["Set_CoolTempNone"] = "Temperatura: este portátil no se la comunica a Windows",
            ["Set_CoolSpeed"] = "Velocidad de la CPU: {0}% del máximo{1}",
            ["Set_CoolOk"] = "Windows no está ralentizando la CPU para enfriarla.",
            ["Set_CoolThrottled"] = "▲ Windows está ralentizando la CPU para enfriarla (permitido: {0}%).",
            ["Set_CoolLimit"] = "Límite de velocidad de la CPU:",
            ["Set_CoolNone"] = "Sin límite",
            ["Set_CoolApply"] = "Aplicar límite",
            ["Set_CoolCurrent"] = "Plan de energía actual: conectado {0}%, con batería {1}%",
            ["Set_CoolUnavailable"] = "Este plan de energía no ofrece un límite de velocidad de la CPU.",

            ["Ck_Drv_OlderUnusedBuiltIn"] = "Más antigua, integrada en Windows",
            ["Ck_DrvBuiltInName"] = "integrado",
            ["Ck_DrvOnlyBuiltIn"] = "No hay nada que quitar: las copias antiguas elegidas son controladores integrados de Windows (no tienen nombre oemNN.inf). Solo Windows puede reemplazarlas y no hace falta quitarlas. Las copias antiguas de controladores instalados después, por ejemplo de AMD, Intel o ASUS, muestran un nombre oemNN.inf y se pueden quitar.",
            ["Ck_DrvBuiltInKept"] = "Se dejaron {0} copia(s) antigua(s) integrada(s) de Windows: son de Windows y no se pueden quitar desde aquí.",

            ["Set_WindowTitle"] = "Ventana",
            ["Set_KeepTray"] = "Seguir ejecutándose en la bandeja al cerrar la ventana",
            ["Set_KeepTrayHint"] = "El botón de cerrar solo oculta la ventana y la aplicación sigue funcionando: la alerta de carga y la optimización automática continúan, y el icono queda junto al reloj (puede estar tras la flecha ^). Haz clic derecho en el icono y elige Salir para cerrar. Desactívalo para que el botón de cerrar cierre la aplicación.",
            ["Msg_TrayStillRunning"] = "Sigue ejecutándose en la bandeja. Haz clic derecho en este icono y elige Salir para cerrar.",

            ["Btn_RestartExplorer"] = "Reiniciar el Explorador",
            ["Btn_RestartExplorerHint"] = "Reinicia el shell de Windows: barra de tareas, Inicio y ventanas del Explorador de archivos. El Explorador crece tras días de uso y reiniciarlo es la única forma de recuperar esa memoria.",
            ["Dlg_ExplorerTitle"] = "¿Reiniciar el Explorador de Windows?",
            ["Dlg_ExplorerMessage"] = "La barra de tareas, el escritorio y todas las ventanas abiertas del Explorador de archivos se cierran y vuelven en unos segundos. Una copia de archivos en una ventana del Explorador se interrumpe. Tus otros programas siguen funcionando.",
            ["Msg_BlockedExplorer"] = "'{0}' es el shell de Windows, así que aquí no se puede finalizar, ralentizar ni recortar. Usa Reiniciar el Explorador para restablecer su memoria.",
