            ["Tab_Power"] = "Energía y refrigeración",
            ["Pw_Title"] = "Ajustes del plan de energía",
            ["Pw_Hint"] = "Cambian el plan de energía activo, por separado con corriente y con batería. Cada cambio se confirma, se comprueba después y Deshacer lo revierte. La aplicación de tu portátil (como MyASUS) también puede cambiar el plan.",
            ["Pw_ActivePlan"] = "Plan de energía activo: {0}",
            ["Pw_AdviceTitle"] = "Sugerencias para este portátil",
            ["Pw_Reading"] = "Leyendo los ajustes de energía…",
            ["Pw_AdviceNone"] = "Nada en estos ajustes parece fuera de lo normal.",
            ["Pw_AdviceMinCpu"] = "El estado mínimo del procesador es {0}% con corriente y {1}% con batería. La CPU no puede bajar de esa velocidad en reposo, lo que aumenta el calor y el ruido del ventilador. El plan Equilibrado de Windows usa 5%.",
            ["Pw_AdvicePerf"] = "Con corriente, el plan pide a la CPU el máximo rendimiento (preferencia de energía {0}, aumento agresivo). Es el ajuste más rápido y también el más caliente y ruidoso. Si el ventilador molesta, sube la preferencia de energía o elige el modo de aumento Eficiente.",
            ["Pw_AdviceMinAboveMax"] = "El estado mínimo del procesador ({0}% / {1}%) es superior al límite de velocidad de la CPU ({2}% / {3}%). Windows podría mantener entonces la CPU en el límite incluso en reposo.",
            ["Pw_AdviceSleep"] = "El portátil se suspende a los {0} min con corriente. Cada suspensión y reanudación es otra oportunidad de que falle un controlador o el firmware al reanudar; un tiempo mayor, o Nunca con corriente, significa menos.",
            ["Pw_AdviceWake"] = "Se permiten los temporizadores de reactivación, así que una tarea programada puede despertar el portátil, incluso dentro de una mochila. «Solo importantes» o Desactivar lo evita.",
