            ["Pw_UsbSuspend"] = "Suspensión selectiva de USB", ["Pw_UsbSuspend_d"] = "Permite a Windows apagar los dispositivos USB inactivos para ahorrar batería. Desactívala si un dispositivo USB se desconecta.",
