            ["Dlg_SaverTitle"] = "Laptop-Sparmodus",
            ["Dlg_SaverMessage"] = "Diese Telemetrie-/Hersteller-Hintergrundprozesse erhalten die Priorität „Niedriger als normal“, und ihr RAM wird verkleinert. Nichts wird beendet oder deaktiviert; „Rückgängig“ stellt die Prioritäten wieder her.",
