            ["Msg_ProcessAiTool"] = "'{0}' gehört zur lokalen KI-Toolchain (Modell-Host oder Agent-Laufzeit) und wird daher nie verkleinert, gedrosselt oder eingefroren. Es wirkt inaktiv, während es auf die GPU oder einen anderen Prozess wartet.",
            ["Msg_ProcessInteractive"] = "'{0}' ist eine interaktive App (Browser/Shell); das Senken der Priorität ist blockiert, um Verzögerungen zu vermeiden. Normal oder höher ist erlaubt. Aktivieren Sie „Drosseln interaktiver Apps erlauben“, um das zu umgehen.",
