            ["Sec_Idle"] = "Leerlauf",
            ["Sec_HibernateHint"] = "Beim Schließen des Deckels im Akkubetrieb in den Ruhezustand statt in den Energiesparmodus wechseln. Der Energiesparmodus verbraucht viele Stunden lang etwas Strom; der Ruhezustand schreibt den RAM auf die Festplatte und verbraucht keinen. Nicht alle Laptops unterstützen die Umstellung (reine Modern-Standby-Hardware ignoriert sie eventuell) – bei einem Fehlschlag wird das gemeldet, statt Erfolg vorzutäuschen.",
            ["Sec_HibernateLine"] = "Aktion beim Schließen des Deckels im Akkubetrieb: {0}",
