            ["Tab_Tweaks"] = "Optimierungen",
            ["Tw_Hint"] = "Ausgewählte, umkehrbare Registrierungsoptimierungen. Das Ausschalten stellt den Windows-Standard wieder her; „Rückgängig“ stellt Ihren genauen vorherigen Wert wieder her. Sicherheitsfunktionen werden nie angetastet. Manche Änderungen erfordern eine Abmeldung.",
