            ["Msg_SmbUnblocked"] = "Blockierung für eingehendes SMB entfernt.",
            ["Msg_SecurityFailed"] = "Sicherheitsänderung für {0} fehlgeschlagen: {1}",
            ["Chk_AllowInteractiveThrottle"] = "Drosseln interaktiver Apps erlauben",
            ["Chk_AllowInteractiveThrottleHint"] = "Erlaubt, Browsern, Shells und anderen interaktiven Apps die Priorität Leerlauf/Niedriger als normal zu geben. Standardmäßig aus, weil es beim Wechsel zu diesen Apps sichtbare Verzögerungen verursachen kann. Sicherheits-/systemkritische Prozesse bleiben in jedem Fall geschützt.",
            ["Chk_AutoOptimize"] = "Auto-Optimierung (RAM-abhängig)",
            ["Chk_AutoOptimizeHint"] = "Überwacht den freien RAM alle 5 s. Fällt er unter den Schwellenwert, wird bei Hintergrundprozessen, die eine Weile im Leerlauf sind (nahe 0% CPU), der RAM verkleinert und die Priorität auf „Niedriger als normal“ gesenkt. Browser, Shell und die gerade aktive App bleiben unberührt. Alles wird automatisch wiederhergestellt, sobald sich der RAM erholt.",
            ["Lbl_FreeRamBelow"] = "Freier RAM unter:",
            ["Chk_AllowSuspend"] = "Anhalten lange inaktiver Apps erlauben",
            ["Chk_AllowSuspendHint"] = "Zusätzlich zum Senken der Priorität werden Hintergrund-Apps, die etwa 5 Minuten im Leerlauf waren, vollständig angehalten (eingefroren). Sie nutzen dabei keine CPU und laufen sofort weiter, wenn Sie zu ihnen wechseln oder „Alle angehaltenen fortsetzen“ verwenden.",
