            ["Msg_Resumed"] = "'{0}' (PID {1}) fortgesetzt.",
            ["Msg_ResumeFailed"] = "'{0}' konnte nicht fortgesetzt werden: {1}",
            ["Dlg_AutoSuspendTitle"] = "Automatisches Anhalten erlauben?",
            ["Dlg_AutoSuspendMessage"] = "Die Auto-Optimierung beginnt, Hintergrund-Apps, die etwa 5 Minuten im Leerlauf waren, einzufrieren (0% CPU), sobald der freie RAM unter Ihren Schwellenwert fällt – ohne Nachfrage pro App. Bekannte Virenschutz-/EDR-/Backup-Agenten werden nie angehalten. Sie können jederzeit mit „Alle angehaltenen fortsetzen“ alles fortsetzen und die Funktion durch Abwählen von „Anhalten lange inaktiver Apps erlauben“ ausschalten.",
            ["Lbl_SuspendedCount"] = "{0} angehalten",
            ["Tab_Checks"] = "Prüfungen",
            ["Ck_Hint"] = "Die Prüfungen schauen nur nach: Es wird nichts gelöscht oder geändert, außer dem Entfernen alter, nicht verwendeter Treiber im Tab „Doppelte Treiber“, das vorher nachfragt. Sieh dir die Ergebnisse an und handle selbst.",
