            ["Ck_PathGone"] = "Dieser Ort existiert nicht mehr.",
            ["Ck_LeftTitle"] = "Gelöschte Programme: Reste und Dateien, die noch im Speicher sind",
            ["Ck_LeftHint"] = "Sucht (1) Ordner in Program Files, die keinem installierten Programm gehören, (2) Einträge unter „Installierte Apps“, deren Dateien fehlen, und (3) Programme, die laufen oder Bibliotheken aus Dateien geladen haben, die von der Festplatte gelöscht wurden. Starte diese Programme neu, um sie freizugeben. Sieh dir einen Ordner an, bevor du ihn löschst: Er kann zu Software gehören, die ohne normales Deinstallationsprogramm installiert wurde.",
