            ["Ck_DupTitle"] = "Doppelte Dateien",
            ["Ck_DupHint"] = "Sucht Dateien mit identischem Inhalt (gleiche Größe, dann gleicher SHA-256-Hash) ab 1 MB. Standardmäßig werden Downloads, Dokumente, Desktop, Bilder, Videos und Musik durchsucht. Dateien, die nur in der Cloud liegen, werden übersprungen, damit nichts heruntergeladen wird. Es wird nichts gelöscht: Behalte selbst jeweils eine Kopie pro Gruppe.",
            ["Ck_DupScanDefault"] = "Meine Ordner prüfen",
            ["Ck_DupScanFolder"] = "Ordner wählen…",
            ["Ck_DupFolderPrompt"] = "Ordner zum Suchen nach doppelten Dateien wählen",
            ["Ck_DupProgress"] = "Wird geprüft… {0} Datei(en) angesehen",
            ["Ck_DupComparing"] = "{0} Kandidat(en) werden verglichen…",
            ["Ck_DupSummary"] = "{0} Gruppe(n) identischer Dateien; wenn von jeder nur eine Kopie bleibt, werden {1} frei.",
            ["Ck_DrvTitle"] = "Doppelte Treiber",
            ["Ck_DrvHint"] = "Windows bewahrt alte Treiberversionen im Treiberspeicher auf. Hier stehen Treiber, die mehrfach gespeichert sind, und welche Kopie verwendet wird oder die neueste ist. Alte Kopien sind harmlos: Sie belegen nur Speicherplatz und ermöglichen ggf. ein Zurücksetzen. „Ordner öffnen“ zeigt die Dateien der gewählten Kopie. „Ausgewählte entfernen…“ löscht Kopien mit dem Status „Ältere, nicht in Verwendung“ per pnputil /delete-driver (nie mit /force, Windows lehnt also ab, was ein Gerät noch nutzt); die neueste Kopie, Kopien in Verwendung und Kopien ohne Datum oder oemNN.inf-Namen werden nie angeboten.",
            ["Ck_Drv_NewestInUse"] = "Neueste, in Verwendung",
            ["Ck_Drv_OlderInUse"] = "Ältere, in Verwendung",
