            ["Ck_Drv_OlderUnused"] = "Ältere, nicht in Verwendung",
            ["Ck_DrvSummary"] = "{0} Treiber mehrfach gespeichert; ältere, nicht verwendete Kopien belegen {1}.",
            ["Tab_Settings"] = "Einstellungen",
            ["Set_ModeTitle"] = "Modus",
            ["Set_ViewOnly"] = "Nur-Ansicht-Modus",
            ["Set_ViewOnlyHint"] = "BG Optimizer beobachtet nur und zeigt, was es tun würde. Es bremst, friert, kürzt oder beendet keine Prozesse, ändert keine Autostart-Einträge, Dienste, Sicherheitseinstellungen oder Tweaks, bereinigt keine Dateien und erstellt keine Wiederherstellungspunkte. Die Auto-Optimierung läuft weiter und schreibt ins Protokoll, was sie getan hätte. Was sie schon gebremst oder eingefroren hatte, wird beim Einschalten freigegeben.",
            ["Set_ViewOnlyBanner"] = "Nur-Ansicht-Modus ist an: Es wird nichts geändert.",
            ["Msg_ViewOnlyNothingChanged"] = "Der Nur-Ansicht-Modus ist an, daher wurde nichts geändert. Schalte ihn in den Einstellungen aus, um Änderungen vorzunehmen.",
            ["Msg_ViewOnlyBlocked"] = "Nur-Ansicht-Modus ist an: „{0}“ wurde nicht geändert.",
            ["Msg_ViewOnlyOn"] = "Nur-Ansicht-Modus an: Die App beobachtet nur. Was sie gebremst oder eingefroren hatte, wurde freigegeben.",
            ["Msg_ViewOnlyOff"] = "Nur-Ansicht-Modus aus: Die App kann wieder Änderungen vornehmen.",
            ["Msg_ViewOnlyWouldThrottle"] = "Nur Ansicht: würde die Priorität senken und den RAM von „{0}“ (PID {1}) kürzen, der im Hintergrund untätig ist.",
            ["Msg_ViewOnlyWouldSuspend"] = "Nur Ansicht: würde „{0}“ (PID {1}) einfrieren, lange untätig.",
            ["Set_ViewOnlyNoSelect"] = "Solange er an ist, lassen sich in den Listen Prozesse, Autostart-Apps und Dienste keine Zeilen auswählen.",
            ["Set_CodeTitle"] = "Code-Sperre",
            ["Set_CodeHint"] = "Lege einen geheimen Code (mindestens 8 Zeichen) fest, damit der Nur-Ansicht-Modus nur von jemandem ausgeschaltet werden kann, der ihn kennt. Code und Modus werden dort gespeichert, wo nur ein Administrator sie ändern kann; andere Programme, die unter deinem Konto laufen, können die Sperre also nicht durch Bearbeiten einer Datei aufheben. Einen Administrator hält das nicht auf. Code vergessen? Lösche als Administrator den Registrierungsschlüssel HKEY_LOCAL_MACHINE\\SOFTWARE\\BgOptimizer.",
            ["Set_CodeOn"] = "Code-Sperre: an",
            ["Set_CodeOff"] = "Code-Sperre: aus",
