            ["Msg_ViewOnlyStays"] = "Der Nur-Ansicht-Modus bleibt an: Der Code wurde nicht eingegeben.",
            ["Msg_ViewOnlyCodeSet"] = "Code-Sperre festgelegt: Zum Ausschalten des Nur-Ansicht-Modus ist jetzt der Code nötig.",
            ["Msg_ViewOnlyCodeChanged"] = "Code-Sperre: Der Code wurde geändert.",
            ["Msg_ViewOnlyCodeRemoved"] = "Code-Sperre entfernt: Der Nur-Ansicht-Modus lässt sich ohne Code ausschalten.",
            ["Msg_ViewOnlyCodeWrong"] = "Es wurde ein falscher Nur-Ansicht-Code eingegeben.",
            ["Msg_ViewOnlyNotSaved"] = "Die Einstellung für Nur-Ansicht-Modus oder Code konnte nicht gespeichert werden (zum Schreiben in den geschützten Speicher sind Administratorrechte nötig); sie bleibt nach einem Neustart nicht erhalten.",
            ["Msg_ViewOnlyCodeLegacy"] = "In settings.json wurde eine alte Code-Sperre aus Version 1.2.0 gefunden; ihr wird nicht mehr vertraut (diese Datei kann jedes Programm unter deinem Konto ändern). Lege in den Einstellungen einen neuen Code fest, um den Nur-Ansicht-Modus wieder zu sperren.",
