            ["St_DetailMissing"] = "Die Datei, auf die dieser Eintrag zeigt, existiert nicht mehr, daher bewirkt er beim Start nichts. Er kann bedenkenlos deaktiviert bleiben.",
            ["St_DetailLocked"] = "Das Deaktivieren ist für diesen Eintrag gesperrt (Sicherheitssoftware, eine Windows-Komponente oder diese App). Einschalten ist weiterhin möglich.",
            ["St_DetailReadOnly"] = "Diese Art von Eintrag lässt sich hier nicht umschalten. Nutze die Schaltfläche „Windows-Starteinstellungen öffnen“ oder die Einstellungen des Programms selbst.",
            ["St_OpenSettings"] = "Windows-Starteinstellungen öffnen",
            ["Msg_StartupReadOnly"] = "„{0}“ lässt sich hier nicht umschalten (schreibgeschützter Eintrag). Nutze Windows-Einstellungen > Apps > Autostart.",
            ["Msg_StartupLocked"] = "„{0}“ ist geschützt (Sicherheitssoftware, eine Windows-Komponente oder diese App) und kann hier nicht deaktiviert werden.",
            ["Msg_StartupReenabled"] = "„{0}“ hat sich nach dem Deaktivieren hier selbst wieder eingeschaltet: Das Programm schreibt seinen Autostart-Eintrag neu. Deaktiviere es in den Einstellungen des Programms.",
            ["Ck_PathNotLocal"] = "Nicht geöffnet: Dieser Ort liegt nicht auf einem lokalen Laufwerk dieses PCs.",
            ["Ck_DrvOpenFolder"] = "Ordner öffnen",
            ["Ck_DrvSelectOld"] = "Alte, unbenutzte wählen",
            ["Ck_DrvDelete"] = "Ausgewählte entfernen…",
            ["Ck_DrvNoneDeletable"] = "Nichts zu entfernen. Wähle Zeilen mit dem Status „Ältere, nicht in Verwendung“ (oder klicke auf „Alte, unbenutzte wählen“).",
            ["Ck_DrvDeleteMsg"] = "Diese alten Treiberkopien werden mit pnputil aus dem Windows-Treiberspeicher entfernt (nie mit /force, Windows lehnt also ab, was ein Gerät noch nutzt). Vorher wird ein Wiederherstellungspunkt erstellt, wenn diese Option aktiv ist. Eine entfernte Kopie lässt sich von hier aus nicht zurückholen.",
            ["Ck_DrvRemoved"] = "Alter Treiber {0} ({1}) wurde aus dem Treiberspeicher entfernt.",
            ["Ck_DrvRemoveFailed"] = "Treiber {0} konnte nicht entfernt werden: {1}",
            ["Ck_DrvNotRemovable"] = "„{0}“ wurde nicht entfernt: Nur ältere, nicht verwendete Kopien können entfernt werden.",
            ["Ck_DrvRemovedTotal"] = "{0} alte Treiberkopie(n) entfernt; etwa {1} freigegeben.",
            ["Set_LoadOptimize"] = "Automatisch optimieren, wenn die Last über dem Limit bleibt",
            ["Set_LoadOptimizeHint"] = "Nach etwa 15 Sekunden über dem Limit wird bei Hintergrundprogrammen, die eine Weile untätig waren, der RAM freigegeben und die Priorität auf „Niedriger als normal“ gesenkt; das gilt, bis jede Last mindestens 5 Punkte unter dem Limit liegt. Das Programm, das du gerade nutzt, Browser, Audio-Apps, Sicherheitssoftware und KI-Werkzeuge werden nie angefasst, und nichts wird eingefroren (Einfrieren bleibt an wenig freien RAM gebunden). Im reinen Ansichtsmodus wird nur ins Protokoll geschrieben, was getan würde. Die App aktualisiert im Infobereich weiter, solange das aktiv ist.",
            ["Msg_LegacyStartupFixed"] = "{0} Autostart-Eintrag/-Einträge aus einer älteren Version repariert. Sie bleiben ausgeschaltet, und Windows fragt nicht mehr, mit welcher App sie geöffnet werden sollen.",
            ["Msg_ThresholdCapped"] = "Die Schwelle für freien Arbeitsspeicher wurde von {0} GB auf {1} GB gesenkt, ein Drittel der {2} GB dieses PCs. Sonst wäre die automatische Optimierung ständig aktiv und würde Programme dauernd verkleinern.",
            ["Msg_ProcessPlatform"] = "'{0}' ist ein Hilfsprozess von Windows oder eines Hardwaretreibers (Energie, WLAN, Sicherheit oder Grafik) und wird daher nie gedrosselt, verkleinert oder eingefroren. Ein Drosseln kann Ruhezustand und Aufwachen stören.",
            ["Msg_ProcessUserProtected"] = "'{0}' steht auf Ihrer Liste „Nie anfassen“ in den Einstellungen und wird daher nie gedrosselt, verkleinert oder eingefroren.",
            ["Msg_RulesCleared"] = "{0} dauerhafte Drosselungsregel(n) für Programme entfernt, die nicht gedrosselt werden dürfen: {1}.",
            ["Set_NeverTitle"] = "Programme, die nie angefasst werden",
            ["Set_NeverHint"] = "Programmnamen durch Kommas getrennt, zum Beispiel: AnyDesk, MyVpnClient. Die automatische Optimierung und jede andere Drosselung überspringt sie. Tragen Sie Arbeits-Agenten ein, die untätig sind, aber erreichbar bleiben müssen: Fernzugriff, VPN, Chat, E-Mail, Synchronisierung, Passwort-Manager.",
            ["Set_NeverName"] = "Programme, die nie angefasst werden, Namen durch Kommas getrennt",
            ["Set_CoolTitle"] = "Kühlung",
            ["Set_CoolHint"] = "Die Lüfterdrehzahl bestimmt die Firmware des Laptops selbst (bei ASUS: MyASUS, Lüftermodus). Windows hat keine sichere Lüfterschnittstelle, und diese App installiert keinen Treiber. Die Höchstgeschwindigkeit der CPU zu begrenzen ist der einzige Hebel, der bei jedem Laptop Wärme und Lüftergeräusch senkt. Wird alle 5 Sekunden aktualisiert, solange dieses Fenster offen ist.",
            ["Set_CoolTemp"] = "Temperatur: {0} °C",
            ["Set_CoolTempNone"] = "Temperatur: Dieser Laptop meldet sie nicht an Windows",
            ["Set_CoolSpeed"] = "CPU-Takt: {0} % des Maximums{1}",
            ["Set_CoolOk"] = "Windows drosselt die CPU nicht zur Kühlung.",
            ["Set_CoolThrottled"] = "▲ Windows drosselt die CPU zur Kühlung (erlaubt: {0} %).",
            ["Set_CoolLimit"] = "CPU-Geschwindigkeitslimit:",
            ["Set_CoolNone"] = "Kein Limit",
            ["Set_CoolApply"] = "Limit anwenden",
            ["Set_CoolCurrent"] = "Aktueller Energiesparplan: Netzbetrieb {0} %, Akkubetrieb {1} %",
            ["Set_CoolUnavailable"] = "Dieser Energiesparplan bietet kein CPU-Geschwindigkeitslimit.",

            ["Ck_Drv_OlderUnusedBuiltIn"] = "Ältere, in Windows integriert",
            ["Ck_DrvBuiltInName"] = "integriert",
            ["Ck_DrvOnlyBuiltIn"] = "Nichts zu entfernen: Die gewählten älteren Kopien sind in Windows integrierte Treiber (sie haben keinen oemNN.inf-Namen). Nur Windows kann sie ersetzen, und sie müssen nicht weg. Ältere Kopien später installierter Treiber, etwa von AMD, Intel oder ASUS, zeigen einen oemNN.inf-Namen und lassen sich entfernen.",
            ["Ck_DrvBuiltInKept"] = "{0} ältere integrierte Windows-Kopie(n) unangetastet: Sie gehören Windows und lassen sich hier nicht entfernen.",

            ["Set_WindowTitle"] = "Fenster",
            ["Set_KeepTray"] = "Im Infobereich weiterlaufen, wenn ich das Fenster schließe",
            ["Set_KeepTrayHint"] = "Die Schließen-Schaltfläche blendet nur das Fenster aus, und die App arbeitet weiter: Lastwarnung und automatische Optimierung laufen weiter, und das Symbol bleibt neben der Uhr (eventuell hinter dem Pfeil ^). Zum Beenden das Symbol rechts anklicken und Beenden wählen. Schalten Sie das aus, damit die Schließen-Schaltfläche die App beendet.",
            ["Msg_TrayStillRunning"] = "Läuft weiter im Infobereich. Zum Beenden dieses Symbol rechts anklicken und Beenden wählen.",

            ["Btn_RestartExplorer"] = "Explorer neu starten",
            ["Btn_RestartExplorerHint"] = "Startet die Windows-Shell neu: Taskleiste, Start und Datei-Explorer-Fenster. Der Explorer wächst im Lauf der Tage, und nur ein Neustart gibt diesen Speicher zurück.",
            ["Dlg_ExplorerTitle"] = "Windows-Explorer neu starten?",
            ["Dlg_ExplorerMessage"] = "Taskleiste, Desktop und alle geöffneten Datei-Explorer-Fenster schließen sich und sind nach wenigen Sekunden wieder da. Ein laufender Kopiervorgang in einem Datei-Explorer-Fenster wird unterbrochen. Ihre anderen Programme laufen weiter.",
            ["Msg_BlockedExplorer"] = "„{0}“ ist die Windows-Shell und kann hier nicht beendet, gedrosselt oder verkleinert werden. Mit „Explorer neu starten“ setzen Sie seinen Speicher zurück.",
            ["Msg_ExplorerRestarted"] = "Windows-Explorer neu gestartet (er belegte {0} MB).",
            ["Msg_ExplorerNotFound"] = "In dieser Sitzung wurde keine Explorer-Shell zum Neustarten gefunden.",
            ["Msg_ExplorerNotBack"] = "Der Explorer wurde beendet, aber Windows hat innerhalb von 15 Sekunden keinen neuen gestartet. Drücken Sie Strg+Umschalt+Esc, wählen Sie „Neuen Task ausführen“ und geben Sie explorer ein.",
            ["Msg_ExplorerNoAutoRestart"] = "Nicht neu gestartet: Windows ist so eingestellt, dass es die Shell nicht selbst neu startet (oder es wird eine eigene Shell verwendet); das Beenden des Explorers könnte Sie ohne Desktop zurücklassen.",
            ["Msg_ExplorerFailed"] = "Der Explorer konnte nicht neu gestartet werden: {0}",

