            ["Tab_Power"] = "Energie & Kühlung",
            ["Pw_Title"] = "Einstellungen des Energiesparplans",
            ["Pw_Hint"] = "Ändern den aktiven Energiesparplan, getrennt für Netzbetrieb und Akkubetrieb. Jede Änderung wird bestätigt, danach geprüft, und „Rückgängig“ stellt sie wieder her. Auch die App Ihres Laptops (etwa MyASUS) kann den Plan ändern.",
            ["Pw_ActivePlan"] = "Aktiver Energiesparplan: {0}",
            ["Pw_AdviceTitle"] = "Vorschläge für diesen Laptop",
            ["Pw_Reading"] = "Energieeinstellungen werden gelesen…",
            ["Pw_AdviceNone"] = "Nichts in diesen Einstellungen wirkt ungewöhnlich.",
            ["Pw_AdviceMinCpu"] = "Der minimale Prozessorzustand beträgt {0}% im Netzbetrieb und {1}% im Akkubetrieb. Die CPU darf im Leerlauf nicht unter diese Geschwindigkeit fallen, was Wärme und Lüftergeräusch erhöht. Der Ausbalanciert-Plan von Windows verwendet 5%.",
            ["Pw_AdvicePerf"] = "Im Netzbetrieb verlangt der Plan von der CPU maximale Leistung (Energiepräferenz {0}, aggressiver Boost). Das ist die schnellste, aber auch heißeste und lauteste Einstellung. Stört der Lüfter, erhöhen Sie die Energiepräferenz oder wählen Sie den Boost-Modus Effizient.",
            ["Pw_AdviceMinAboveMax"] = "Der minimale Prozessorzustand ({0}% / {1}%) liegt über dem CPU-Geschwindigkeitslimit ({2}% / {3}%). Windows hält die CPU dann womöglich auch im Leerlauf am Limit.",
            ["Pw_AdviceSleep"] = "Im Netzbetrieb geht der Laptop nach {0} Min. in den Energiesparmodus. Jedes Einschlafen und Aufwachen ist eine weitere Gelegenheit für ein Treiber- oder Firmwareproblem beim Aufwachen; eine längere Zeit oder „Nie“ im Netzbetrieb bedeutet weniger davon.",
            ["Pw_AdviceWake"] = "Weckzeitgeber sind erlaubt, sodass eine geplante Aufgabe den Laptop wecken kann, auch in der Tasche. „Nur wichtige“ oder Deaktivieren verhindert das.",
