            ["Pw_Sleep"] = "Energiesparmodus nach", ["Pw_Sleep_d"] = "Leerlaufzeit bis zum Energiesparmodus. Bei den meisten neuen Laptops ist das Modern Standby: Der Bildschirm ist aus, doch der Laptop wacht weiter für Netzwerk und Updates auf.",
            ["Pw_HibernateAfter"] = "Ruhezustand nach", ["Pw_HibernateAfter_d"] = "Zeit im Energiesparmodus, bevor der Laptop alles auf die Festplatte schreibt und sich ausschaltet, was keinen Akku verbraucht.",
