            ["Pw_CpuMin"] = "Minimaler Prozessorzustand", ["Pw_CpuMin_d"] = "Die niedrigste Geschwindigkeit, auf die die CPU im Leerlauf fallen darf, als Anteil des Maximums. Weniger heißt im Leerlauf kühler und leiser.",
            ["Pw_UsbSuspend"] = "Selektives USB-Energiesparen", ["Pw_UsbSuspend_d"] = "Erlaubt Windows, inaktive USB-Geräte abzuschalten, um Akku zu sparen. Deaktivieren, wenn ein USB-Gerät aussetzt.",
            ["Pw_WifiPower"] = "WLAN-Energiesparen", ["Pw_WifiPower_d"] = "Wie stark der WLAN-Adapter zwischen Paketen schlafen darf. „Maximale Leistung“ reagiert am schnellsten.",
            ["Pw_Aspm"] = "PCI-Express-Verbindungsenergiesparen", ["Pw_Aspm_d"] = "Lässt die Verbindung zu SSD und Grafik in einem sparsameren Zustand ruhen. „Aus“ ist am kompatibelsten.",
            ["Pw_Boost"] = "Prozessor-Boost-Modus", ["Pw_Boost_d"] = "Wie bereitwillig die CPU über ihre Basisgeschwindigkeit geht. Deaktiviert oder Effizient läuft kühler und leiser.",
            ["Pw_Epp"] = "Energiepräferenz", ["Pw_Epp_d"] = "0 bevorzugt Leistung, 100 bevorzugt Energiesparen. Wird von CPUs genutzt, die ihre Geschwindigkeit selbst wählen.",
            ["Pw_CoolPolicy"] = "Kühlungsrichtlinie", ["Pw_CoolPolicy_d"] = "Wenn die CPU heiß wird: Aktiv dreht zuerst die Lüfter hoch, Passiv drosselt zuerst die CPU.",
