            ["Msg_SmbBlocked"] = "SMB in ingresso bloccato.",
            ["Msg_SmbUnblocked"] = "Blocco SMB in ingresso rimosso.",
            ["Msg_SecurityFailed"] = "Modifica di sicurezza non riuscita per {0}: {1}",
            ["Chk_AllowInteractiveThrottle"] = "Consenti limitazione app interattive",
            ["Chk_AllowInteractiveThrottleHint"] = "Permette di impostare la priorità Inattiva/Inferiore al normale su browser, shell e altre app interattive. Disattivato per impostazione predefinita perché può causare rallentamenti visibili quando passi a queste app. I processi di sicurezza/critici di sistema restano comunque protetti.",
            ["Chk_AutoOptimize"] = "Auto-ottimizzazione (in base alla RAM)",
            ["Chk_AutoOptimizeHint"] = "Controlla la RAM libera ogni 5 s. Quando scende sotto la soglia, i processi in background inattivi (vicino allo 0% di CPU) da un po' vedono ridotta la RAM e la priorità portata a Inferiore al normale. Non tocca mai il browser, la shell o l'app attualmente attiva. Ripristina tutto automaticamente quando la RAM si riprende.",
