            ["Dlg_AutoSuspendTitle"] = "Consentire la sospensione automatica?",
            ["Dlg_AutoSuspendMessage"] = "L'auto-ottimizzazione inizierà a congelare (0% di CPU) le app in background inattive da circa 5 minuti ogni volta che la RAM libera scende sotto la soglia, senza conferma per ogni app. Antivirus/EDR/agenti di backup noti non vengono mai sospesi. Puoi riprendere tutto in qualsiasi momento con «Riprendi tutte le sospese» e disattivare la funzione deselezionando «Consenti sospensione delle app inattive da molto».",
            ["Lbl_SuspendedCount"] = "{0} sospesi",
            ["Tab_Checks"] = "Controlli",
            ["Ck_Hint"] = "I controlli si limitano a guardare: non viene eliminato né modificato nulla, tranne la rimozione dei vecchi driver inutilizzati nella scheda dei driver duplicati, che chiede prima conferma. Esamina i risultati e agisci tu.",
