            ["Ck_PathGone"] = "Questa posizione non esiste più.",
            ["Ck_LeftTitle"] = "Programmi eliminati: resti e file ancora in memoria",
            ["Ck_LeftHint"] = "Cerca (1) cartelle in Program Files che non appartengono ad alcun programma installato, (2) voci in App installate i cui file non esistono più e (3) programmi in esecuzione o con librerie caricate da file eliminati dal disco. Riavvia questi programmi per rilasciarli. Controlla una cartella prima di eliminarla: potrebbe appartenere a software installato senza un normale programma di disinstallazione.",
