            ["Ck_Col_Provider"] = "Fornitore",
            ["Ck_DupTitle"] = "File duplicati",
            ["Ck_DupHint"] = "Cerca file con contenuto identico (stessa dimensione, poi stesso hash SHA-256) di 1 MB o più. Per impostazione predefinita guarda in Download, Documenti, Desktop, Immagini, Video e Musica. I file disponibili solo online nel cloud vengono saltati, così non viene scaricato nulla. Non viene eliminato nulla: conserva tu una copia per ogni gruppo.",
            ["Ck_DupScanDefault"] = "Analizza le mie cartelle",
            ["Ck_DupScanFolder"] = "Scegli cartella…",
            ["Ck_DupFolderPrompt"] = "Scegli una cartella in cui cercare file duplicati",
            ["Ck_DupProgress"] = "Analisi… {0} file esaminati",
            ["Ck_DupComparing"] = "Confronto di {0} file candidati…",
            ["Ck_DupSummary"] = "{0} gruppo/i di file identici; tenendo una copia per ciascuno si libererebbero {1}.",
            ["Ck_DrvTitle"] = "Driver duplicati",
            ["Ck_DrvHint"] = "Windows conserva le vecchie versioni di un driver nel proprio archivio dei driver. Qui sono elencati i driver salvati più di una volta e si indica quale copia è in uso o è la più recente. Le copie vecchie sono innocue: occupano solo spazio e possono permettere un ripristino. «Apri cartella» mostra i file della copia selezionata. «Rimuovi selezionati…» elimina le copie contrassegnate «Più vecchia, non in uso» con pnputil /delete-driver (mai con /force, quindi Windows rifiuta quelle che un dispositivo usa ancora); la copia più recente, quelle in uso e quelle senza data o senza nome oemNN.inf non vengono mai proposte.",
            ["Ck_Drv_NewestInUse"] = "Più recente, in uso",
            ["Ck_Drv_OlderInUse"] = "Più vecchia, in uso",
            ["Ck_Drv_NewestUnused"] = "Più recente, non in uso",
            ["Ck_Drv_OlderUnused"] = "Più vecchia, non in uso",
            ["Ck_DrvSummary"] = "{0} driver salvati più di una volta; le copie più vecchie non in uso occupano {1}.",
            ["Tab_Settings"] = "Impostazioni",
            ["Set_ModeTitle"] = "Modalità",
            ["Set_ViewOnly"] = "Modalità sola visualizzazione",
            ["Set_ViewOnlyHint"] = "BG Optimizer si limita a osservare e mostra cosa farebbe. Non rallenta, congela, riduce né chiude processi, non modifica elementi di avvio, servizi, impostazioni di sicurezza o tweak, non pulisce file e non crea punti di ripristino. L'ottimizzazione automatica continua a funzionare e scrive nel registro cosa avrebbe fatto. Ciò che aveva già rallentato o congelato viene rilasciato all'attivazione.",
            ["Set_ViewOnlyBanner"] = "Modalità sola visualizzazione attiva: non viene modificato nulla.",
            ["Msg_ViewOnlyNothingChanged"] = "La modalità sola visualizzazione è attiva, quindi non è stato modificato nulla. Disattivala nelle Impostazioni per apportare modifiche.",
            ["Msg_ViewOnlyBlocked"] = "Modalità sola visualizzazione attiva: «{0}» non è stato modificato.",
            ["Msg_ViewOnlyOn"] = "Modalità sola visualizzazione attiva: l'app si limita a osservare. Ciò che aveva rallentato o congelato è stato rilasciato.",
            ["Msg_ViewOnlyOff"] = "Modalità sola visualizzazione disattivata: l'app può di nuovo apportare modifiche.",
            ["Msg_ViewOnlyWouldThrottle"] = "Sola visualizzazione: abbasserebbe la priorità e ridurrebbe la RAM di «{0}» (PID {1}), inattivo in background.",
            ["Msg_ViewOnlyWouldSuspend"] = "Sola visualizzazione: congelerebbe «{0}» (PID {1}), inattivo da molto tempo.",
            ["Set_ViewOnlyNoSelect"] = "Finché è attiva, nelle liste Processi, App di avvio e Servizi non si possono selezionare righe.",
            ["Set_CodeTitle"] = "Blocco con codice",
            ["Set_CodeHint"] = "Imposta un codice segreto (almeno 8 caratteri) in modo che la modalità sola visualizzazione possa essere disattivata solo da chi lo conosce. Il codice e la modalità sono conservati dove solo un amministratore può modificarli, quindi altri programmi eseguiti con il tuo account non possono togliere il blocco modificando un file. Non ferma un amministratore. Hai dimenticato il codice? Come amministratore, elimina la chiave del registro HKEY_LOCAL_MACHINE\\SOFTWARE\\BgOptimizer.",
            ["Set_CodeOn"] = "Blocco con codice: attivo",
            ["Set_CodeOff"] = "Blocco con codice: disattivato",
            ["Set_CodeSet"] = "Imposta codice…",
