            ["Msg_ProcessPlatform"] = "'{0}' è un componente di supporto di Windows o di un driver hardware (alimentazione, Wi-Fi, sicurezza o grafica), quindi non viene mai rallentato, ridotto o congelato. Rallentarlo può disturbare sospensione e ripresa.",
