            ["Ck_Col_Provider"] = "Dostawca",
            ["Ck_DupTitle"] = "Zduplikowane pliki",
            ["Ck_DupHint"] = "Wyszukuje pliki o identycznej zawartości (ten sam rozmiar, potem ten sam skrót SHA-256) o rozmiarze co najmniej 1 MB. Domyślnie przeszukuje Pobrane, Dokumenty, Pulpit, Obrazy, Wideo i Muzykę. Pliki dostępne tylko online w chmurze są pomijane, aby nic nie było pobierane. Nic nie jest usuwane: zachowaj samodzielnie po jednej kopii z każdej grupy.",
            ["Ck_DupScanDefault"] = "Skanuj moje foldery",
            ["Ck_DupScanFolder"] = "Wybierz folder…",
            ["Ck_DupFolderPrompt"] = "Wybierz folder, w którym szukać zduplikowanych plików",
            ["Ck_DupProgress"] = "Skanowanie… przejrzano plików: {0}",
            ["Ck_DupComparing"] = "Porównywanie plików kandydatów: {0}…",
            ["Ck_DupSummary"] = "Grup identycznych plików: {0}; pozostawienie po jednej kopii zwolniłoby {1}.",
            ["Ck_DrvTitle"] = "Zduplikowane sterowniki",
            ["Ck_DrvHint"] = "Windows przechowuje stare wersje sterownika w magazynie sterowników. Tu widać sterowniki zapisane więcej niż raz oraz to, która kopia jest używana lub najnowsza. Stare kopie są nieszkodliwe: zajmują tylko miejsce i mogą umożliwić powrót do poprzedniej wersji. „Otwórz folder” pokazuje pliki wybranej kopii. „Usuń wybrane…” usuwa kopie oznaczone „Starsza, nieużywana” przez pnputil /delete-driver (nigdy z /force, więc Windows odmówi usunięcia tych, których urządzenie jeszcze używa); najnowsza kopia, kopie używane oraz kopie bez daty lub nazwy oemNN.inf nigdy nie są proponowane.",
            ["Ck_Drv_NewestInUse"] = "Najnowsza, używana",
            ["Ck_Drv_OlderInUse"] = "Starsza, używana",
            ["Ck_Drv_NewestUnused"] = "Najnowsza, nieużywana",
            ["Ck_Drv_OlderUnused"] = "Starsza, nieużywana",
            ["Ck_DrvSummary"] = "Sterowników zapisanych więcej niż raz: {0}; starsze, nieużywane kopie zajmują {1}.",
            ["Tab_Settings"] = "Ustawienia",
            ["Set_ModeTitle"] = "Tryb",
            ["Set_ViewOnly"] = "Tryb tylko podglądu",
            ["Set_ViewOnlyHint"] = "BG Optimizer tylko obserwuje i pokazuje, co by zrobił. Nie spowalnia, nie zamraża, nie przycina ani nie zamyka procesów, nie zmienia elementów autostartu, usług, ustawień zabezpieczeń ani tweaków, nie czyści plików i nie tworzy punktów przywracania. Automatyczna optymalizacja nadal działa i zapisuje w dzienniku, co by zrobiła. To, co już spowolniła lub zamroziła, jest zwalniane po włączeniu.",
            ["Set_ViewOnlyBanner"] = "Tryb tylko podglądu jest włączony: nic nie jest zmieniane.",
            ["Msg_ViewOnlyNothingChanged"] = "Tryb tylko podglądu jest włączony, więc nic nie zmieniono. Wyłącz go w Ustawieniach, aby wprowadzać zmiany.",
            ["Msg_ViewOnlyBlocked"] = "Tryb tylko podglądu jest włączony: „{0}” nie został zmieniony.",
            ["Msg_ViewOnlyOn"] = "Tryb tylko podglądu włączony: aplikacja tylko obserwuje. Wszystko, co spowolniła lub zamroziła, zostało zwolnione.",
            ["Msg_ViewOnlyOff"] = "Tryb tylko podglądu wyłączony: aplikacja znów może wprowadzać zmiany.",
            ["Msg_ViewOnlyWouldThrottle"] = "Tylko podgląd: obniżyłaby priorytet i przycięła pamięć RAM „{0}” (PID {1}), bezczynnego w tle.",
            ["Msg_ViewOnlyWouldSuspend"] = "Tylko podgląd: zamroziłaby „{0}” (PID {1}), długo bezczynny.",
            ["Set_ViewOnlyNoSelect"] = "Gdy jest włączony, w listach Procesy, Aplikacje startowe i Usługi nie można zaznaczać wierszy.",
            ["Set_CodeTitle"] = "Blokada kodem",
            ["Set_CodeHint"] = "Ustaw tajny kod (co najmniej 8 znaków), aby tryb tylko podglądu mogła wyłączyć wyłącznie osoba, która go zna. Kod i tryb są przechowywane tam, gdzie zmienić je może tylko administrator, więc inne programy uruchomione na Twoim koncie nie wyłączą blokady, edytując plik. Administratora to nie powstrzyma. Nie pamiętasz kodu? Jako administrator usuń klucz rejestru HKEY_LOCAL_MACHINE\\SOFTWARE\\BgOptimizer.",
            ["Set_CodeOn"] = "Blokada kodem: włączona",
