            ["Set_CodeTooShort"] = "Minimalna długość kodu: {0}.",
            ["Set_CodeWait"] = "Zbyt wiele błędnych prób. Spróbuj ponownie za {0} s.",
            ["Msg_ViewOnlyStays"] = "Tryb tylko podglądu pozostaje włączony: nie wpisano kodu.",
            ["Msg_ViewOnlyCodeSet"] = "Ustawiono blokadę kodem: wyłączenie trybu tylko podglądu wymaga teraz kodu.",
            ["Msg_ViewOnlyCodeChanged"] = "Blokada kodem: kod został zmieniony.",
            ["Msg_ViewOnlyCodeRemoved"] = "Usunięto blokadę kodem: tryb tylko podglądu można wyłączyć bez kodu.",
            ["Msg_ViewOnlyCodeWrong"] = "Wpisano zły kod trybu tylko podglądu.",
            ["Msg_ViewOnlyNotSaved"] = "Nie udało się zapisać ustawienia trybu tylko podglądu ani kodu (zapis w chronionym magazynie wymaga uprawnień administratora), więc nie przetrwa ono ponownego uruchomienia.",
            ["Msg_ViewOnlyCodeLegacy"] = "W settings.json znaleziono starą blokadę kodem z wersji 1.2.0 i nie jest już ona uznawana za wiarygodną (ten plik może zmienić każdy program uruchomiony na Twoim koncie). Ustaw nowy kod w Ustawieniach, aby ponownie zablokować tryb tylko podglądu.",
            ["Set_LoadTitle"] = "Obciążenie systemu",
            ["Set_LoadHint"] = "Obciążenie na żywo, odświeżane co 5 sekund, gdy to okno jest otwarte. Biała linia na każdym pasku to Twój limit; powyżej niego pasek robi się czerwony.",
            ["Set_LoadDisk"] = "Aktywność dysku",
