            ["Set_LoadAlert"] = "Powiadom mnie, gdy obciążenie utrzymuje się powyżej limitu",
            ["Set_LoadAlertHint"] = "Po około 15 sekundach powyżej limitu w dzienniku zapisywana jest linia z najbardziej obciążającymi programami, a gdy okno jest ukryte, pokazywane jest powiadomienie w zasobniku (najwyżej raz na 5 minut dla każdego obciążenia). Gdy to włączone, aplikacja odświeża dane także w zasobniku.",
