            ["St_DetailLocked"] = "Wyłączanie jest zablokowane dla tego elementu (oprogramowanie zabezpieczające, składnik systemu Windows lub ta aplikacja). Nadal możesz go włączyć.",
            ["St_DetailReadOnly"] = "Tego rodzaju wpisu nie można tu przełączyć. Użyj przycisku „Otwórz ustawienia autostartu systemu Windows” lub ustawień samego programu.",
            ["St_OpenSettings"] = "Otwórz ustawienia autostartu systemu Windows",
            ["Msg_StartupReadOnly"] = "„{0}” nie można tu przełączyć (wpis tylko do odczytu). Użyj Ustawienia systemu Windows > Aplikacje > Uruchamianie.",
            ["Msg_StartupLocked"] = "„{0}” jest chroniony (oprogramowanie zabezpieczające, składnik systemu Windows lub ta aplikacja) i nie można go tu wyłączyć.",
            ["Msg_StartupReenabled"] = "„{0}” włączył się ponownie po wyłączeniu tutaj: program sam przepisuje swój wpis autostartu. Wyłącz go w ustawieniach samego programu.",
