            ["Ck_DrvDelete"] = "Usuń wybrane…",
            ["Ck_DrvNoneDeletable"] = "Nie ma czego usuwać. Zaznacz wiersze oznaczone „Starsza, nieużywana” (albo kliknij „Zaznacz stare, nieużywane”).",
            ["Ck_DrvDeleteMsg"] = "Te stare kopie sterowników zostaną usunięte z magazynu sterowników Windows przez pnputil (nigdy z /force, więc Windows odmówi usunięcia tych, których urządzenie jeszcze używa). Najpierw tworzony jest punkt przywracania, jeśli ta opcja jest włączona. Usuniętej kopii nie da się stąd przywrócić.",
            ["Ck_DrvRemoved"] = "Usunięto stary sterownik {0} ({1}) z magazynu sterowników.",
            ["Ck_DrvRemoveFailed"] = "Nie udało się usunąć sterownika {0}: {1}",
            ["Ck_DrvNotRemovable"] = "„{0}” nie został usunięty: można usuwać tylko starsze kopie, które nie są używane.",
            ["Ck_DrvRemovedTotal"] = "Usunięto starych kopii sterowników: {0}; zwolniono około {1}.",
            ["Set_LoadOptimize"] = "Optymalizuj automatycznie, gdy obciążenie utrzymuje się powyżej limitu",
            ["Set_LoadOptimizeHint"] = "Po około 15 sekundach powyżej limitu programom w tle, które przez jakiś czas były bezczynne, zwalniana jest pamięć RAM, a priorytet obniżany do „Poniżej normalnego”; trwa to, aż każde obciążenie spadnie o co najmniej 5 punktów poniżej limitu. Program, z którego korzystasz, przeglądarki, aplikacje audio, oprogramowanie zabezpieczające i narzędzia AI nigdy nie są ruszane, a nic nie jest zamrażane (zamrażanie pozostaje związane z małą ilością wolnej pamięci RAM). W trybie tylko do podglądu zapisuje w dzienniku jedynie to, co by zrobiła. Aplikacja odświeża dane w zasobniku, dopóki ta opcja jest włączona.",
            ["Msg_LegacyStartupFixed"] = "Naprawiono elementy autostartu pozostawione przez starszą wersję: {0}. Pozostają wyłączone, a Windows nie pyta już, jaką aplikacją je otworzyć.",
            ["Msg_ThresholdCapped"] = "Próg wolnej pamięci RAM obniżono z {0} GB do {1} GB, czyli jednej trzeciej z {2} GB tego komputera. W przeciwnym razie automatyczna optymalizacja działałaby bez przerwy i ciągle zmniejszałaby programy.",
            ["Msg_ProcessPlatform"] = "'{0}' to pomocniczy proces Windows lub sterownika sprzętu (zasilanie, Wi-Fi, bezpieczeństwo lub grafika), więc nigdy nie jest spowalniany, zmniejszany ani zamrażany. Spowalnianie takich procesów może zakłócać usypianie i wybudzanie.",
            ["Msg_ProcessUserProtected"] = "'{0}' jest na Twojej liście „nie ruszać” w Ustawieniach, więc nigdy nie jest spowalniany, zmniejszany ani zamrażany.",
            ["Msg_RulesCleared"] = "Usunięto stałe reguły spowalniania ({0}) dla programów, których nie wolno spowalniać: {1}.",
            ["Set_NeverTitle"] = "Programy, których nigdy nie ruszać",
            ["Set_NeverHint"] = "Nazwy programów oddzielone przecinkami, na przykład: AnyDesk, MyVpnClient. Automatyczna optymalizacja i każde inne spowalnianie je pomija. Dodaj agentów służbowych, które bezczynnie czekają, ale muszą pozostać osiągalne: zdalny dostęp, VPN, czat, poczta, synchronizacja, menedżery haseł.",
            ["Set_NeverName"] = "Programy, których nigdy nie ruszać, nazwy oddzielone przecinkami",
            ["Set_CoolTitle"] = "Chłodzenie",
            ["Set_CoolHint"] = "Prędkością wentylatora steruje oprogramowanie sprzętowe samego laptopa (w ASUS: MyASUS, tryb wentylatora). Windows nie ma bezpiecznego interfejsu wentylatora, a ta aplikacja nie instaluje sterownika. Ograniczenie maksymalnej prędkości procesora to jedyna dźwignia, która zmniejsza ciepło i hałas wentylatora w każdym laptopie. Odświeżane co 5 sekund, gdy to okno jest otwarte.",
            ["Set_CoolTemp"] = "Temperatura: {0} °C",
            ["Set_CoolTempNone"] = "Temperatura: ten laptop nie przekazuje jej systemowi Windows",
            ["Set_CoolSpeed"] = "Prędkość procesora: {0}% maksimum{1}",
            ["Set_CoolOk"] = "Windows nie spowalnia procesora w celu chłodzenia.",
            ["Set_CoolThrottled"] = "▲ Windows spowalnia procesor w celu chłodzenia (dozwolone: {0}%).",
            ["Set_CoolLimit"] = "Limit prędkości procesora:",
            ["Set_CoolNone"] = "Bez limitu",
            ["Set_CoolApply"] = "Zastosuj limit",
            ["Set_CoolCurrent"] = "Bieżący plan zasilania: z zasilaczem {0}%, na baterii {1}%",
            ["Set_CoolUnavailable"] = "Ten plan zasilania nie oferuje limitu prędkości procesora.",

            ["Ck_Drv_OlderUnusedBuiltIn"] = "Starsza, wbudowana w Windows",
            ["Ck_DrvBuiltInName"] = "wbudowany",
            ["Ck_DrvOnlyBuiltIn"] = "Nie ma czego usuwać: wybrane starsze kopie to wbudowane sterowniki samego Windows (nie mają nazwy oemNN.inf). Zastąpić je może tylko Windows i nie trzeba ich usuwać. Starsze kopie sterowników zainstalowanych później, na przykład od AMD, Intel czy ASUS, mają nazwę oemNN.inf i można je usunąć.",
            ["Ck_DrvBuiltInKept"] = "Pozostawiono bez zmian starszych wbudowanych kopii Windows: {0}. Należą do Windows i nie można ich stąd usunąć.",

            ["Set_WindowTitle"] = "Okno",
            ["Set_KeepTray"] = "Działaj w zasobniku po zamknięciu okna",
            ["Set_KeepTrayHint"] = "Przycisk zamykania tylko ukrywa okno, a aplikacja działa dalej: alert obciążenia i automatyczna optymalizacja nadal pracują, a ikona zostaje obok zegara (może być za strzałką ^). Aby zakończyć, kliknij ikonę prawym przyciskiem i wybierz Zakończ. Wyłącz tę opcję, aby przycisk zamykania kończył aplikację.",
            ["Msg_TrayStillRunning"] = "Nadal działa w zasobniku. Aby zakończyć, kliknij tę ikonę prawym przyciskiem i wybierz Zakończ.",

            ["Btn_RestartExplorer"] = "Uruchom ponownie Eksploratora",
            ["Btn_RestartExplorerHint"] = "Uruchamia ponownie powłokę Windows: pasek zadań, Start i okna Eksploratora plików. Eksplorator rośnie po dniach pracy, a tylko restart zwraca tę pamięć.",
            ["Dlg_ExplorerTitle"] = "Uruchomić ponownie Eksploratora Windows?",
            ["Dlg_ExplorerMessage"] = "Pasek zadań, pulpit i wszystkie otwarte okna Eksploratora plików zamkną się i wrócą po kilku sekundach. Trwające kopiowanie plików w oknie Eksploratora zostanie przerwane. Pozostałe programy działają dalej.",
            ["Msg_BlockedExplorer"] = "„{0}” to powłoka Windows, więc nie można jej tu zakończyć, spowolnić ani przyciąć. Użyj „Uruchom ponownie Eksploratora”, aby zresetować jej pamięć.",
            ["Msg_ExplorerRestarted"] = "Eksplorator Windows uruchomiony ponownie (zajmował {0} MB).",
            ["Msg_ExplorerNotFound"] = "W tej sesji nie znaleziono powłoki Eksploratora do ponownego uruchomienia.",
            ["Msg_ExplorerNotBack"] = "Eksplorator został zamknięty, ale Windows nie uruchomił nowego w ciągu 15 sekund. Naciśnij Ctrl+Shift+Esc, wybierz Uruchom nowe zadanie i wpisz explorer.",
            ["Msg_ExplorerNoAutoRestart"] = "Nie uruchomiono ponownie: Windows jest ustawiony tak, by nie uruchamiać powłoki samodzielnie (lub używana jest inna powłoka), więc zamknięcie Eksploratora mogłoby zostawić Cię bez pulpitu.",
            ["Msg_ExplorerFailed"] = "Nie udało się uruchomić ponownie Eksploratora: {0}",

            ["Set_NeverIntro"] = "Aplikacja nigdy nie spowalnia, nie przycina ani nie zamraża tych programów. Wbudowana lista jest zawsze włączona; poniżej możesz dodać własne nazwy.",
