            ["Chk_AllowInteractiveThrottleHint"] = "Позволяет задавать приоритет «Простой»/«Ниже среднего» браузерам, оболочкам и другим интерактивным приложениям. По умолчанию выключено, так как при переключении на них возможны заметные задержки. Процессы безопасности и критичные для системы остаются защищёнными в любом случае.",
            ["Chk_AutoOptimize"] = "Авто-оптимизация (по ОЗУ)",
            ["Chk_AutoOptimizeHint"] = "Проверяет свободную ОЗУ каждые 5 с. Когда она падает ниже порога, у фоновых процессов, некоторое время простаивающих (около 0% ЦП), сжимается ОЗУ и понижается приоритет до «Ниже среднего». Никогда не затрагивает браузер, оболочку и текущее активное приложение. Всё восстанавливается автоматически, когда ОЗУ освободится.",
