            ["Ck_DupTitle"] = "Дубликаты файлов",
            ["Ck_DupHint"] = "Ищет файлы с одинаковым содержимым (одинаковый размер, затем одинаковый хеш SHA-256) размером от 1 МБ. По умолчанию просматривает Загрузки, Документы, Рабочий стол, Изображения, Видео и Музыку. Файлы, находящиеся только в облаке, пропускаются, чтобы ничего не скачивалось. Ничего не удаляется: оставьте по одной копии из каждой группы самостоятельно.",
            ["Ck_DupScanDefault"] = "Сканировать мои папки",
