            ["Ck_DupSummary"] = "Групп одинаковых файлов: {0}; если оставить по одной копии, освободится {1}.",
            ["Ck_DrvTitle"] = "Дубликаты драйверов",
            ["Ck_DrvHint"] = "Windows хранит старые версии драйвера в хранилище драйверов. Здесь показаны драйверы, сохранённые более одного раза, и какая копия используется или самая новая. Старые копии безвредны: они лишь занимают место и могут позволить откат. «Открыть папку» показывает файлы выбранной копии. «Удалить выбранные…» удаляет копии со статусом «Более старый, не используется» через pnputil /delete-driver (никогда не /force, поэтому Windows откажет, если устройство ещё использует драйвер); самая новая копия, копии в использовании и копии без даты или имени oemNN.inf не предлагаются.",
            ["Ck_Drv_NewestInUse"] = "Самый новый, используется",
            ["Ck_Drv_OlderInUse"] = "Более старый, используется",
            ["Ck_Drv_NewestUnused"] = "Самый новый, не используется",
            ["Ck_Drv_OlderUnused"] = "Более старый, не используется",
            ["Ck_DrvSummary"] = "Групп драйверов, сохранённых более одного раза: {0}; старые неиспользуемые копии занимают {1}.",
            ["Tab_Settings"] = "Настройки",
            ["Set_ModeTitle"] = "Режим",
            ["Set_ViewOnly"] = "Режим только просмотра",
            ["Set_ViewOnlyHint"] = "BG Optimizer только наблюдает и показывает, что сделал бы. Он не замедляет, не замораживает, не сжимает и не закрывает процессы, не меняет автозапуск, службы, настройки безопасности и твики, не очищает файлы и не создаёт точки восстановления. Авто-оптимизация продолжает работать и записывает в журнал, что сделала бы. Всё, что она уже замедлила или заморозила, освобождается при включении.",
            ["Set_ViewOnlyBanner"] = "Режим только просмотра включён: ничего не меняется.",
            ["Msg_ViewOnlyNothingChanged"] = "Режим только просмотра включён, поэтому ничего не изменено. Отключите его в Настройках, чтобы вносить изменения.",
            ["Msg_ViewOnlyBlocked"] = "Режим только просмотра включён: «{0}» не изменён.",
            ["Msg_ViewOnlyOn"] = "Режим только просмотра включён: программа только наблюдает. Всё, что она замедлила или заморозила, освобождено.",
            ["Msg_ViewOnlyOff"] = "Режим только просмотра отключён: программа снова может вносить изменения.",
