            ["Set_ViewOnlyNoSelect"] = "Пока режим включён, строки в списках «Процессы», «Автозагрузка» и «Службы» нельзя выбирать.",
            ["Set_CodeTitle"] = "Защита кодом",
            ["Set_CodeHint"] = "Задайте секретный код (не менее 8 символов), чтобы режим только просмотра мог отключить только тот, кто его знает. Код и режим хранятся там, где их может изменить только администратор, поэтому другие программы, работающие от вашего имени, не смогут снять защиту, отредактировав файл. Администратора это не остановит. Забыли код? От имени администратора удалите раздел реестра HKEY_LOCAL_MACHINE\\SOFTWARE\\BgOptimizer.",
