            ["Msg_ViewOnlyNotSaved"] = "Не удалось сохранить настройку режима только просмотра или кода (для записи в защищённое хранилище нужны права администратора), поэтому она не сохранится после перезапуска.",
            ["Msg_ViewOnlyCodeLegacy"] = "В settings.json найдена старая защита кодом из версии 1.2.0, ей больше не доверяют (этот файл может изменить любая программа, работающая от вашего имени). Задайте новый код в Настройках, чтобы снова заблокировать режим только просмотра.",
            ["Set_LoadTitle"] = "Нагрузка системы",
            ["Set_LoadHint"] = "Нагрузка в реальном времени, обновляется каждые 5 с, пока окно открыто. Белая линия на каждой полосе — ваш лимит; выше него полоса краснеет.",
            ["Set_LoadDisk"] = "Активность диска",
