            ["St_DetailLocked"] = "Отключение для этого элемента заблокировано (защитное ПО, компонент Windows или это приложение). Включить его всё равно можно.",
            ["St_DetailReadOnly"] = "Этот вид записи здесь не переключается. Воспользуйтесь кнопкой «Открыть параметры автозагрузки Windows» или настройками самой программы.",
            ["St_OpenSettings"] = "Открыть параметры автозагрузки Windows",
            ["Msg_StartupReadOnly"] = "«{0}» здесь не переключается (запись только для чтения). Используйте Параметры Windows > Приложения > Автозагрузка.",
            ["Msg_StartupLocked"] = "«{0}» защищён (защитное ПО, компонент Windows или это приложение) и не может быть отключён здесь.",
            ["Msg_StartupReenabled"] = "«{0}» снова включился сам после отключения здесь: программа переписывает собственную запись автозагрузки. Отключите его в настройках самой программы.",
            ["Ck_PathNotLocal"] = "Не открыто: это расположение не на локальном диске этого ПК.",
            ["Ck_DrvOpenFolder"] = "Открыть папку",
