            ["Ck_DrvDelete"] = "Удалить выбранные…",
            ["Ck_DrvNoneDeletable"] = "Удалять нечего. Выберите строки со статусом «Более старый, не используется» (или нажмите «Выбрать старые, неиспользуемые»).",
            ["Ck_DrvDeleteMsg"] = "Эти старые копии драйверов будут удалены из хранилища драйверов Windows через pnputil (никогда не /force, поэтому Windows откажет, если устройство ещё использует драйвер). Сначала создаётся точка восстановления, если эта опция включена. Удалённую копию отсюда вернуть нельзя.",
            ["Ck_DrvRemoved"] = "Старый драйвер {0} ({1}) удалён из хранилища драйверов.",
            ["Ck_DrvRemoveFailed"] = "Не удалось удалить драйвер {0}: {1}",
            ["Ck_DrvNotRemovable"] = "«{0}» не удалён: можно удалять только более старые копии, которые не используются.",
            ["Ck_DrvRemovedTotal"] = "Удалено старых копий драйверов: {0}; освобождено примерно {1}.",
            ["Set_LoadOptimize"] = "Оптимизировать автоматически, когда нагрузка держится выше лимита",
            ["Set_LoadOptimizeHint"] = "Примерно через 15 секунд выше лимита у фоновых программ, которые какое-то время простаивали, освобождается ОЗУ, а приоритет снижается до «Ниже среднего»; так продолжается, пока каждая нагрузка не опустится минимум на 5 пунктов ниже лимита. Программа, которой вы пользуетесь, браузеры, аудиоприложения, средства безопасности и ИИ-инструменты не затрагиваются, и ничего не замораживается (заморозка остаётся привязанной к малому объёму свободной ОЗУ). В режиме только просмотра в журнал пишется лишь то, что было бы сделано. Пока это включено, приложение обновляется и в трее.",
            ["Msg_LegacyStartupFixed"] = "Исправлено элементов автозагрузки, оставшихся от старой версии: {0}. Они остаются выключенными, а Windows больше не спрашивает, чем их открыть.",
            ["Msg_ThresholdCapped"] = "Порог свободной ОЗУ снижен с {0} GB до {1} GB — это треть от {2} GB этого ПК. Иначе автооптимизация работала бы постоянно и без конца сжимала бы программы.",
            ["Msg_ProcessPlatform"] = "'{0}' — вспомогательный процесс Windows или драйвера оборудования (питание, Wi-Fi, безопасность или графика), поэтому его никогда не замедляют, не сжимают и не замораживают. Замедление таких процессов может нарушить сон и пробуждение.",
            ["Msg_ProcessUserProtected"] = "'{0}' есть в вашем списке «не трогать» в Настройках, поэтому его никогда не замедляют, не сжимают и не замораживают.",
            ["Msg_RulesCleared"] = "Удалено постоянных правил замедления: {0} (для программ, которые нельзя замедлять): {1}.",
            ["Set_NeverTitle"] = "Программы, которые не трогать",
            ["Set_NeverHint"] = "Названия программ через запятую, например: AnyDesk, MyVpnClient. Автооптимизация и любые другие замедляющие действия их пропускают. Добавьте рабочие агенты, которые простаивают, но должны оставаться на связи: удалённый доступ, VPN, чат, почта, синхронизация, менеджеры паролей.",
            ["Set_NeverName"] = "Программы, которые не трогать, названия через запятую",
            ["Set_CoolTitle"] = "Охлаждение",
            ["Set_CoolHint"] = "Скоростью вентилятора управляет собственная прошивка ноутбука (на ASUS: MyASUS, режим вентилятора). В Windows нет безопасного интерфейса для вентилятора, а это приложение не устанавливает драйверов. Ограничение максимальной скорости процессора — единственный рычаг, снижающий нагрев и шум вентилятора на любом ноутбуке. Обновляется каждые 5 секунд, пока окно открыто.",
            ["Set_CoolTemp"] = "Температура: {0} °C",
            ["Set_CoolTempNone"] = "Температура: этот ноутбук не сообщает её Windows",
            ["Set_CoolSpeed"] = "Скорость процессора: {0}% от максимума{1}",
            ["Set_CoolOk"] = "Windows не замедляет процессор ради охлаждения.",
            ["Set_CoolThrottled"] = "▲ Windows замедляет процессор ради охлаждения (разрешено: {0}%).",
            ["Set_CoolLimit"] = "Ограничение скорости процессора:",
            ["Set_CoolNone"] = "Без ограничения",
            ["Set_CoolApply"] = "Применить ограничение",
            ["Set_CoolCurrent"] = "Текущая схема питания: от сети {0}%, от батареи {1}%",
            ["Set_CoolUnavailable"] = "Эта схема питания не поддерживает ограничение скорости процессора.",

            ["Ck_Drv_OlderUnusedBuiltIn"] = "Старее, встроен в Windows",
            ["Ck_DrvBuiltInName"] = "встроенный",
            ["Ck_DrvOnlyBuiltIn"] = "Удалять нечего: выбранные старые копии — это встроенные драйверы самой Windows (у них нет имени oemNN.inf). Заменить их может только Windows, и убирать их не нужно. Старые копии драйверов, установленных позже (например, от AMD, Intel или ASUS), имеют имя oemNN.inf, и их можно удалить.",
            ["Ck_DrvBuiltInKept"] = "Старых встроенных копий Windows оставлено без изменений: {0}. Они принадлежат Windows и отсюда не удаляются.",

            ["Set_WindowTitle"] = "Окно",
            ["Set_KeepTray"] = "Оставаться в трее при закрытии окна",
            ["Set_KeepTrayHint"] = "Кнопка закрытия только скрывает окно, а программа продолжает работать: оповещение о нагрузке и автооптимизация не прекращаются, а значок остаётся у часов (он может быть за стрелкой ^). Чтобы выйти, щёлкните значок правой кнопкой и выберите «Выйти». Отключите параметр, чтобы кнопка закрытия полностью выходила из программы.",
            ["Msg_TrayStillRunning"] = "Программа работает в трее. Чтобы выйти, щёлкните этот значок правой кнопкой и выберите «Выйти».",

            ["Btn_RestartExplorer"] = "Перезапустить Проводник",
            ["Btn_RestartExplorerHint"] = "Перезапускает оболочку Windows: панель задач, «Пуск» и окна Проводника. Проводник разрастается за дни работы, и вернуть эту память можно только перезапуском.",
            ["Dlg_ExplorerTitle"] = "Перезапустить Проводник Windows?",
            ["Dlg_ExplorerMessage"] = "Панель задач, рабочий стол и все открытые окна Проводника закроются и через несколько секунд вернутся. Копирование файлов в окне Проводника будет прервано. Остальные программы продолжают работать.",
            ["Msg_BlockedExplorer"] = "«{0}» — это оболочка Windows, поэтому её нельзя завершить, замедлить или сжать отсюда. Чтобы сбросить её память, используйте «Перезапустить Проводник».",
            ["Msg_ExplorerRestarted"] = "Проводник Windows перезапущен (он занимал {0} МБ).",
            ["Msg_ExplorerNotFound"] = "В этом сеансе не найдена оболочка Проводника для перезапуска.",
            ["Msg_ExplorerNotBack"] = "Проводник закрыт, но Windows не запустила новый за 15 секунд. Нажмите Ctrl+Shift+Esc, выберите «Запустить новую задачу» и введите explorer.",
            ["Msg_ExplorerNoAutoRestart"] = "Не перезапущено: Windows настроена не перезапускать оболочку сама (или используется другая оболочка), поэтому закрытие Проводника могло бы оставить вас без рабочего стола.",
            ["Msg_ExplorerFailed"] = "Не удалось перезапустить Проводник: {0}",

            ["Set_NeverIntro"] = "Программа никогда не замедляет, не сжимает и не замораживает эти программы. Встроенный список действует всегда; ниже можно добавить свои названия.",
            ["Set_NeverBuiltIn"] = "Всегда защищено (встроенный список, не отключается): названий программ — {0}, групп — {1}.",
            ["Set_NeverShowList"] = "Показать, что защищено",
