            ["Tab_Power"] = "Питание и охлаждение",
            ["Pw_Title"] = "Параметры схемы питания",
            ["Pw_Hint"] = "Меняют активную схему питания отдельно для работы от сети и от батареи. Каждое изменение подтверждается, затем проверяется, а «Отменить» его возвращает. Схему может менять и программа ноутбука (например, MyASUS).",
            ["Pw_ActivePlan"] = "Активная схема питания: {0}",
            ["Pw_AdviceTitle"] = "Советы для этого ноутбука",
            ["Pw_Reading"] = "Чтение параметров питания…",
            ["Pw_AdviceNone"] = "В этих параметрах нет ничего необычного.",
            ["Pw_AdviceMinCpu"] = "Минимальное состояние процессора: {0}% от сети и {1}% от батареи. Процессору не разрешено простаивать на скорости ниже этой, из-за чего больше тепла и шума вентилятора. Сбалансированная схема Windows использует 5%.",
            ["Pw_AdvicePerf"] = "От сети схема требует от процессора максимальной производительности (приоритет энергии {0}, агрессивный режим повышения). Это самый быстрый вариант, но и самый горячий и шумный. Если мешает вентилятор, увеличьте приоритет энергии или выберите режим повышения «Эффективный».",
            ["Pw_AdviceMinAboveMax"] = "Минимальное состояние процессора ({0}% / {1}%) выше ограничения скорости процессора ({2}% / {3}%). Тогда Windows может держать процессор на пределе ограничения даже в простое.",
            ["Pw_AdviceSleep"] = "От сети ноутбук засыпает через {0} мин. Каждое засыпание и пробуждение — ещё один шанс на проблему драйвера или микропрограммы при выходе из сна; большее время или «Никогда» от сети означает их меньше.",
            ["Pw_AdviceWake"] = "Таймеры пробуждения разрешены, поэтому запланированная задача может разбудить ноутбук, даже в сумке. «Только важные» или «Отключить» этому препятствует.",
