            ["Pw_Group_Screen"] = "Экран и сон",
            ["Pw_Group_Lid"] = "Крышка и кнопка питания",
            ["Pw_Group_Cpu"] = "Процессор",
            ["Pw_Group_Devices"] = "Устройства",
            ["Pw_Opt_Disable"] = "Отключить", ["Pw_Opt_Enable"] = "Включить", ["Pw_Opt_ImportantOnly"] = "Только важные",
