            ["Pw_Act_Nothing"] = "Ничего не делать", ["Pw_Act_Sleep"] = "Сон", ["Pw_Act_Hibernate"] = "Гибернация", ["Pw_Act_Shutdown"] = "Завершение работы",
            ["Pw_Wifi_Max"] = "Макс. производительность", ["Pw_Wifi_Low"] = "Низкая экономия", ["Pw_Wifi_Medium"] = "Средняя экономия", ["Pw_Wifi_Saving"] = "Макс. экономия",
            ["Pw_Aspm_Moderate"] = "Умеренная экономия", ["Pw_Aspm_Maximum"] = "Макс. экономия",
            ["Pw_Boost_Aggressive"] = "Агрессивный", ["Pw_Boost_Efficient"] = "Эффективный", ["Pw_Boost_EfficientAggressive"] = "Эффективный агрессивный",
            ["Pw_Cool_Passive"] = "Пассивное", ["Pw_Cool_Active"] = "Активное",
