            ["Pw_Sleep"] = "Переходить в спящий режим через", ["Pw_Sleep_d"] = "Время простоя до сна. На большинстве новых ноутбуков это Modern Standby: экран выключен, но ноутбук по-прежнему просыпается для сети и обновлений.",
            ["Pw_HibernateAfter"] = "Гибернация через", ["Pw_HibernateAfter_d"] = "Сколько ноутбук спит, прежде чем сохранить всё на диск и выключиться, не расходуя батарею.",
            ["Pw_WakeTimers"] = "Разрешить таймеры пробуждения", ["Pw_WakeTimers_d"] = "Могут ли запланированные задачи и программы будить ноутбук из сна.",
