            ["Pw_UsbSuspend"] = "Выборочное приостановление USB", ["Pw_UsbSuspend_d"] = "Позволяет Windows отключать питание простаивающих USB-устройств для экономии батареи. Отключите, если USB-устройство отваливается.",
            ["Pw_WifiPower"] = "Энергосбережение Wi-Fi", ["Pw_WifiPower_d"] = "Насколько адаптер Wi-Fi может засыпать между пакетами. «Макс. производительность» — самый отзывчивый вариант.",
